INSERT INTO `fza_generadorprocesos` (`CODIGO_GENERADOR_PROCESO_GP`, `NOMBRE_GENERADOR_PROCESO_GP`, `PROCESO_GENERADOR_PROCESO_GP`, `INSTANTE_MODIF`, `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`) VALUES
  ('389', 'verifactu_operacion_intracom', '-- =============================================================================\r\n-- Catalogo de calificaciones de operacion para Verifactu + columna en facturas\r\n-- =============================================================================\r\n-- Permite calificar una factura de cara a Verifactu cuando NO es una venta\r\n-- interior en regimen general (intracomunitarias, ISP, exportacion, bienes\r\n-- usados...). El catalogo es ABIERTO: el usuario puede anadir nuevos tipos sin\r\n-- recompilar; el envio lee de aqui el mapeo al XML de la AEAT.\r\n--\r\n-- Mapeo por fila:\r\n--   CLAVE_REGIMEN_VFO     ClaveRegimen (01 general, 03 bienes usados/REBU...).\r\n--   CALIFICACION_VFO      CalificacionOperacion (S1/S2/N1/N2) o vacio.\r\n--   OPERACION_EXENTA_VFO  OperacionExenta (E1..E6) o vacio.\r\n--   ESREPERCUTE_IVA_VFO   \'S\' -> desglose por bandas con tipo y cuota.\r\n--                         \'N\' -> un unico detalle con la base, sin cuota.\r\n--   AMBITO_VFO            Residencia exigida al cliente, para detectar\r\n--                         incoherencias: NACIONAL, UE, EXTRA_UE o CUALQUIERA.\r\n--\r\n-- CALIFICACION y OPERACION_EXENTA son excluyentes: una operacion exenta lleva\r\n-- OperacionExenta; una sujeta (con o sin ISP) lleva CalificacionOperacion.\r\n--\r\n-- Idempotente: tabla con CREATE TABLE IF NOT EXISTS, columnas con chequeo en\r\n-- INFORMATION_SCHEMA, semilla con INSERT IGNORE (no pisa personalizaciones) y\r\n-- backfill del ambito solo en las filas semilla.\r\n-- =============================================================================\r\n-- 1) Tabla catalogo -----------------------------------------------------------\r\nCREATE TABLE IF NOT EXISTS fza_verifactu_operaciones (\r\n  CODIGO_VFO            varchar(20)  NOT NULL,\r\n  DESCRIPCION_VFO       varchar(100) NULL DEFAULT NULL,\r\n  AYUDA_VFO             varchar(255) NULL DEFAULT NULL,\r\n  CLAVE_REGIMEN_VFO     varchar(2)   NULL DEFAULT \'01\',\r\n  CALIFICACION_VFO      varchar(2)   NULL DEFAULT NULL,\r\n  OPERACION_EXENTA_VFO  varchar(2)   NULL DEFAULT NULL,\r\n  ESREPERCUTE_IVA_VFO   varchar(1)   NULL DEFAULT \'S\',\r\n  AMBITO_VFO            varchar(10)  NULL DEFAULT NULL,\r\n  ORDEN_VFO             int(11)      NULL DEFAULT NULL,\r\n  ESACTIVO_VFO          varchar(1)   NULL DEFAULT \'S\',\r\n  INSTANTE_ALTA         datetime     NULL DEFAULT NULL,\r\n  INSTANTE_MODIF        datetime     NULL DEFAULT NULL,\r\n  USUARIO_ALTA          varchar(50)  NULL DEFAULT NULL,\r\n  USUARIO_MODIF         varchar(50)  NULL DEFAULT NULL,\r\n  PRIMARY KEY (CODIGO_VFO)\r\n);\r\n-- 1b) Columna AMBITO_VFO si la tabla ya existia sin ella -----------------------\r\nSET @sExisteAmbito := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_operaciones\'\r\n     AND COLUMN_NAME  = \'AMBITO_VFO\'\r\n);\r\nSET @sSql := IF(@sExisteAmbito = 0,\r\n  \'ALTER TABLE fza_verifactu_operaciones\r\n     ADD COLUMN AMBITO_VFO varchar(10) NULL DEFAULT NULL AFTER ESREPERCUTE_IVA_VFO\',\r\n  \'SELECT \'\'AMBITO_VFO ya existe, se omite\'\' AS info\'\r\n);\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n-- 2) Semilla de tipos habituales (INSERT IGNORE: no pisa lo ya existente) ------\r\nINSERT IGNORE INTO fza_verifactu_operaciones\r\n  (CODIGO_VFO, DESCRIPCION_VFO, AYUDA_VFO, CLAVE_REGIMEN_VFO,\r\n   CALIFICACION_VFO, OPERACION_EXENTA_VFO, ESREPERCUTE_IVA_VFO, AMBITO_VFO,\r\n   ORDEN_VFO, ESACTIVO_VFO, INSTANTE_ALTA, USUARIO_ALTA)\r\nVALUES\r\n  (\'INTERIOR\', \'Interior - regimen general\',\r\n   \'Venta nacional con IVA. Es el comportamiento por defecto.\',\r\n   \'01\', \'S1\', NULL, \'S\', \'NACIONAL\', 10, \'S\', NOW(), \'SEED\'),\r\n  (\'SERVICIO_INTRA\', \'Servicio intracomunitario (no sujeto)\',\r\n   \'Servicio a profesional UE: no sujeto en Espana por localizacion (art. 69), el cliente autoliquida el IVA.\',\r\n   \'01\', \'N2\', NULL, \'N\', \'UE\', 20, \'S\', NOW(), \'SEED\'),\r\n  (\'ENTREGA_INTRA\', \'Entrega intracomunitaria de bienes (exenta)\',\r\n   \'Entrega de bienes a empresa UE, exenta art. 25 LIVA.\',\r\n   \'01\', NULL, \'E5\', \'N\', \'UE\', 30, \'S\', NOW(), \'SEED\'),\r\n  (\'ISP\', \'Inversion del sujeto pasivo\',\r\n   \'El IVA lo autoliquida el destinatario (art. 84). No se repercute cuota.\',\r\n   \'01\', \'S2\', NULL, \'N\', \'CUALQUIERA\', 40, \'S\', NOW(), \'SEED\'),\r\n  (\'EXPORT\', \'Exportacion fuera de la UE (exenta)\',\r\n   \'Entrega de bienes exportados fuera de la UE, exenta art. 21 LIVA. Se asigna sola si el cliente no es de la UE.\',\r\n   \'01\', NULL, \'E2\', \'N\', \'EXTRA_UE\', 50, \'S\', NOW(), \'SEED\'),\r\n  (\'BIENES_USADOS\', \'Bienes usados (REBU)\',\r\n   \'Regimen especial de bienes usados: IVA sobre el margen. INACTIVO: pendiente de implementar el calculo de margen (ver verifactu_rebu.md).\',\r\n   \'03\', \'S1\', NULL, \'S\', \'CUALQUIERA\', 60, \'N\', NOW(), \'SEED\');\r\n-- 2b) Backfill del ambito en filas semilla anteriores sin ambito ---------------\r\nUPDATE fza_verifactu_operaciones SET AMBITO_VFO = \'NACIONAL\'\r\n WHERE CODIGO_VFO = \'INTERIOR\' AND AMBITO_VFO IS NULL;\r\nUPDATE fza_verifactu_operaciones SET AMBITO_VFO = \'UE\'\r\n WHERE CODIGO_VFO IN (\'SERVICIO_INTRA\', \'ENTREGA_INTRA\') AND AMBITO_VFO IS NULL;\r\nUPDATE fza_verifactu_operaciones SET AMBITO_VFO = \'CUALQUIERA\'\r\n WHERE CODIGO_VFO IN (\'ISP\', \'BIENES_USADOS\') AND AMBITO_VFO IS NULL;\r\nUPDATE fza_verifactu_operaciones SET AMBITO_VFO = \'EXTRA_UE\'\r\n WHERE CODIGO_VFO = \'EXPORT\' AND AMBITO_VFO IS NULL;\r\n-- REBU pendiente: se deja inactivo para que no aparezca en el selector. Si se\r\n-- usara tal cual emitiria el IVA sobre la base total, no sobre el margen.\r\nUPDATE fza_verifactu_operaciones SET ESACTIVO_VFO = \'N\'\r\n WHERE CODIGO_VFO = \'BIENES_USADOS\' AND USUARIO_ALTA = \'SEED\';\r\n-- 3) Columna en fza_facturas (FK logica al catalogo) --------------------------\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas\'\r\n     AND COLUMN_NAME  = \'TIPO_OPER_VFACTU_FAC\'\r\n);\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas\r\n     ADD COLUMN TIPO_OPER_VFACTU_FAC varchar(20) NULL DEFAULT NULL\r\n       COMMENT \'\'Calificacion Verifactu: CODIGO_VFO de fza_verifactu_operaciones (NULL=auto)\'\'\r\n     AFTER ESINTRACOMUNITARIO_CLIENTE_FAC\',\r\n  \'SELECT \'\'TIPO_OPER_VFACTU_FAC ya existe, se omite\'\' AS info\'\r\n);\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n-- 4) Recrear las vistas de facturas -------------------------------------------\r\n-- vi_facturas usa SELECT fza_facturas.*, que MariaDB expande a columnas fijas\r\n-- al crear la vista. Hay que recrearla para que TIPO_OPER_VFACTU_FAC quede\r\n-- expuesta al formulario (que enlaza el combo a ese campo). Idempotente.\r\nCREATE OR REPLACE VIEW vi_facturas AS\r\n  SELECT fza_facturas.*,\r\n         fza_formas_pago.DESCRIPCION_FORMA_PAGO_FP AS DESCRIPCION_FORMA_PAGO_FP\r\n    FROM fza_facturas\r\n    LEFT JOIN fza_formas_pago\r\n         ON fza_facturas.FORMA_PAGO_FAC = fza_formas_pago.CODIGO_FP_FP\r\n   ORDER BY fza_facturas.FECHA_FAC DESC;\r\nCREATE OR REPLACE VIEW vi_facturas_normales AS\r\n  SELECT * FROM vi_facturas WHERE TIPO_FAC = \'NORMAL\';\r\nCREATE OR REPLACE VIEW vi_facturas_simplificadas AS\r\n  SELECT * FROM vi_facturas WHERE TIPO_FAC = \'SIMPLIFICADA\';\r\n', '2026-06-14 07:27:06', '2026-06-14 07:27:06', 'Administrador', 'Administrador'),
  ('390', 'vistas_estadisticas', '-- =============================================================================\r\n-- Vistas de estadísticas para informes (BI) — solo lectura sobre fza_*\r\n-- =============================================================================\r\n-- Grano: día x almacén x familia x temporada.\r\n-- No alteran el esquema: CREATE OR REPLACE VIEW (idempotente). No materializan\r\n-- (MariaDB no tiene vistas materializadas); encapsulan la lógica y dejan al\r\n-- panel un SELECT simple.\r\n--\r\n-- IMPORTANTE sobre TEMPORADA:\r\n--   No es columna de fza_articulos. Es la PROPIEDAD \'TEMPORADA\'\r\n--   (fza_propiedades, NIVEL_PROP = \'COLOR\' -> propiedad de 2º nivel) cuyos\r\n--   valores viven en fza_articulos_propiedades con CODIGO_UNIDAD_ARTPROP:\r\n--     \'\'            -> valor a nivel ARTÍCULO\r\n--     ART/COLOR     -> valor a nivel COLOR  (puede variar por color)\r\n--     ART/COLOR/TALLA -> valor a nivel SKU\r\n--   Se resuelve por la clave de color derivada del SKU con SUBSTRING_INDEX,\r\n--   con fallback a nivel artículo. NO se usa vi_articulos (colapsa temporada\r\n--   a un único valor por artículo y multiplicaría filas).\r\n--   Familia SÍ es de artículo (fza_articulos.CODIGO_FAM_ART).\r\n-- =============================================================================\r\n-- 0) Resolver de temporada: una fila por (artículo, clave de nivel)\r\nCREATE OR REPLACE VIEW viest_temporada AS\r\nSELECT\r\n  p.CODIGO_ART_ART                          AS CODIGO_ART,\r\n  p.CODIGO_UNIDAD_ARTPROP                    AS CLAVE_NIVEL,\r\n  COALESCE(pv.PV, p.VALOR_LIBRE_ARTPROP)    AS TEMPORADA\r\nFROM fza_articulos_propiedades p\r\nLEFT JOIN fza_propiedades_valores pv\r\n  ON pv.ID_PV_ARTPROP = p.ID_PV_ARTPROP\r\nWHERE p.CODIGO_PROP_ARTPROP = \'TEMPORADA\';\r\n-- 1) Movimientos de almacén agregados por día\r\nCREATE OR REPLACE VIEW viest_movimientos_dia AS\r\nSELECT\r\n  DATE(m.FECHA_MOV)                              AS FECHA,\r\n  m.CODIGO_ALMACEN_MOV                           AS CODIGO_ALMACEN,\r\n  COALESCE(a.CODIGO_FAM_ART, \'\')               AS CODIGO_FAMILIA,\r\n  COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\') AS TEMPORADA,\r\n  COUNT(*)                                       AS NUM_MOVIMIENTOS,\r\n  COALESCE(SUM(m.CANTIDAD_MOV), 0)             AS UNIDADES_MOV,\r\n  COALESCE(SUM(m.TOTAL_COSTE_MOV), 0)         AS COSTE_MOV\r\nFROM fza_movimientos_almacen m\r\nLEFT JOIN fza_articulos_skus s\r\n  ON s.CODIGO_UNIDAD_SKU = m.CODIGO_UNIDAD_MOV\r\nLEFT JOIN fza_articulos a\r\n  ON a.CODIGO_ART_ART = COALESCE(m.CODIGO_ARTICULO_MOV, s.CODIGO_ART_SKU)\r\nLEFT JOIN viest_temporada tcol\r\n  ON tcol.CODIGO_ART  = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 1)\r\n AND tcol.CLAVE_NIVEL = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 2)\r\nLEFT JOIN viest_temporada tart\r\n  ON tart.CODIGO_ART  = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 1)\r\n AND tart.CLAVE_NIVEL = \'\'\r\nWHERE m.ESACTIVO_MOV = \'S\'\r\nGROUP BY DATE(m.FECHA_MOV), m.CODIGO_ALMACEN_MOV,\r\n         COALESCE(a.CODIGO_FAM_ART, \'\'),\r\n         COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\');\r\n-- 2) Ventas (líneas de factura) agregadas por día\r\nCREATE OR REPLACE VIEW viest_ventas_dia AS\r\nSELECT\r\n  f.FECHA_FAC                                    AS FECHA,\r\n  l.CODIGO_ALM_FACLIN                            AS CODIGO_ALMACEN,\r\n  COALESCE(a.CODIGO_FAM_ART, \'\')               AS CODIGO_FAMILIA,\r\n  COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\') AS TEMPORADA,\r\n  COUNT(*)                                       AS NUM_LINEAS_VENTA,\r\n  COALESCE(SUM(l.CANTIDAD_FACLIN), 0)         AS UNIDADES_VENTA,\r\n  COALESCE(SUM(l.TOTAL_FACLIN), 0)            AS IMPORTE_VENTA\r\nFROM fza_facturas_lineas l\r\nJOIN fza_facturas f\r\n  ON f.NUMERO_FAC = l.NUMERO_FAC_FACLIN\r\n AND f.SERIE_FAC  = l.SERIE_FAC_FACLIN\r\nLEFT JOIN fza_articulos a\r\n  ON a.CODIGO_ART_ART = l.CODIGO_ART_FACLIN\r\nLEFT JOIN viest_temporada tcol\r\n  ON tcol.CODIGO_ART  = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 1)\r\n AND tcol.CLAVE_NIVEL = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 2)\r\nLEFT JOIN viest_temporada tart\r\n  ON tart.CODIGO_ART  = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 1)\r\n AND tart.CLAVE_NIVEL = \'\'\r\nGROUP BY f.FECHA_FAC, l.CODIGO_ALM_FACLIN,\r\n         COALESCE(a.CODIGO_FAM_ART, \'\'),\r\n         COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\');\r\n-- 3) Vista unificada: una fila por (día, almacén, familia, temporada) con\r\n--    todas las medidas. Es la que consultaría el panel/lab.\r\nCREATE OR REPLACE VIEW viest_dia AS\r\nSELECT\r\n  FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n  SUM(NUM_MOVIMIENTOS)  AS NUM_MOVIMIENTOS,\r\n  SUM(UNIDADES_MOV)     AS UNIDADES_MOV,\r\n  SUM(COSTE_MOV)        AS COSTE_MOV,\r\n  SUM(NUM_LINEAS_VENTA) AS NUM_LINEAS_VENTA,\r\n  SUM(UNIDADES_VENTA)   AS UNIDADES_VENTA,\r\n  SUM(IMPORTE_VENTA)    AS IMPORTE_VENTA\r\nFROM (\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n         0 AS NUM_LINEAS_VENTA, 0 AS UNIDADES_VENTA, 0 AS IMPORTE_VENTA\r\n    FROM viest_movimientos_dia\r\n  UNION ALL\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         0, 0, 0,\r\n         NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA\r\n    FROM viest_ventas_dia\r\n) u\r\nGROUP BY FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA;\r\n-- 4) Lista de temporadas (para el combo de filtro del panel)\r\nCREATE OR REPLACE VIEW viest_temporadas AS\r\nSELECT DISTINCT TEMPORADA\r\nFROM viest_temporada\r\nWHERE TEMPORADA IS NOT NULL AND TEMPORADA <> \'\';\r\n-- -----------------------------------------------------------------------------\r\n-- Ejemplo de consulta del panel (comparativa diaria de un rango):\r\n--   SELECT DATEDIFF(FECHA, :pD1) AS BUCKET, SUM(IMPORTE_VENTA) AS VALOR\r\n--     FROM viest_dia\r\n--    WHERE FECHA >= :pD1 AND FECHA <= :pD2\r\n--      AND (:pALM  = \'\' OR CODIGO_ALMACEN = :pALM)\r\n--      AND (:pFAM  = \'\' OR CODIGO_FAMILIA = :pFAM)\r\n--      AND (:pTEMP = \'\' OR TEMPORADA      = :pTEMP)\r\n--    GROUP BY BUCKET ORDER BY BUCKET;\r\n-- OJO rendimiento: una vista con GROUP BY no empuja el filtro de fecha antes\r\n-- de agregar (algoritmo TEMPTABLE), así que para el panel EN VIVO conviene\r\n-- filtrar por fecha sobre las tablas base (como hace el .pas). Estas vistas\r\n-- valen para encapsular la lógica y para el experimento fzaest_.\r\n-- -----------------------------------------------------------------------------\r\n', '2026-06-15 07:21:01', '2026-06-15 07:21:01', 'Administrador', 'Administrador'),
  ('391', 'fzaest_experimental', '-- =============================================================================\r\n-- Experimento de pre-agregado — namespace PROPIO \'fzaest_\' (NO \'fza_\')\r\n-- =============================================================================\r\n-- Para PROBAR si una tabla de acumulados acelera frente a la vista en vivo,\r\n-- sin tocar el esquema real. Todo lo de aquí usa el prefijo \'fzaest_\' (tablas)\r\n-- para diferenciarlo de \'fza_\'. Es desechable: un DROP de las fzaest_* deja la\r\n-- BBDD como estaba. Depende de vistas_estadisticas.sql (lee viest_dia).\r\n--\r\n-- Al ser un sandbox aislado, NO se siguen las convenciones de columnas de\r\n-- \'fza_\' (sufijo por tabla, etc.): nombres planos para legibilidad.\r\n-- =============================================================================\r\n-- Tabla de acumulado diario (mismo grano y medidas que viest_dia)\r\nCREATE TABLE IF NOT EXISTS fzaest_estadisticas_dia (\r\n  FECHA            date          NOT NULL,\r\n  CODIGO_ALMACEN   varchar(10)   NOT NULL,\r\n  CODIGO_FAMILIA   varchar(20)   NOT NULL DEFAULT \'\',\r\n  TEMPORADA        varchar(100)  NOT NULL DEFAULT \'\',\r\n  NUM_MOVIMIENTOS  int           NOT NULL DEFAULT 0,\r\n  UNIDADES_MOV     decimal(19,6) NOT NULL DEFAULT 0,\r\n  COSTE_MOV        decimal(19,6) NOT NULL DEFAULT 0,\r\n  NUM_LINEAS_VENTA int           NOT NULL DEFAULT 0,\r\n  UNIDADES_VENTA   decimal(19,6) NOT NULL DEFAULT 0,\r\n  IMPORTE_VENTA    decimal(19,6) NOT NULL DEFAULT 0,\r\n  INSTANTE_REFRESCO timestamp    NOT NULL DEFAULT CURRENT_TIMESTAMP\r\n                                 ON UPDATE CURRENT_TIMESTAMP,\r\n  PRIMARY KEY (FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA),\r\n  KEY IDX_FZAEST_FAM_FECHA  (CODIGO_FAMILIA, FECHA),\r\n  KEY IDX_FZAEST_TEMP_FECHA (TEMPORADA, FECHA)\r\n);\r\n-- Recálculo incremental de un rango: borra y reinserta solo esos días, de modo\r\n-- que tolera correcciones retroactivas (movimientos anulados, reclasificación\r\n-- de familia/temporada). Se alimenta de la vista unificada.\r\nDROP PROCEDURE IF EXISTS fzaest_recalcular_rango;\r\nDELIMITER //\r\nCREATE PROCEDURE fzaest_recalcular_rango(IN pD1 date, IN pD2 date)\r\nBEGIN\r\n  DELETE FROM fzaest_estadisticas_dia WHERE FECHA BETWEEN pD1 AND pD2;\r\n  INSERT INTO fzaest_estadisticas_dia\r\n    (FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n     NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n     NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA)\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n         NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA\r\n    FROM viest_dia\r\n   WHERE FECHA BETWEEN pD1 AND pD2;\r\nEND //\r\nDELIMITER ;\r\n-- -----------------------------------------------------------------------------\r\n-- Uso / benchmark:\r\n--   CALL fzaest_recalcular_rango(\'2020-01-01\', CURDATE());   -- carga inicial\r\n--   -- Comparar tiempos del MISMO rango largo:\r\n--   --   en vivo:        SELECT ... FROM viest_dia      WHERE ...\r\n--   --   pre-agregado:   SELECT ... FROM fzaest_estadisticas_dia  WHERE ...\r\n-- Limpieza total del experimento:\r\n--   DROP PROCEDURE IF EXISTS fzaest_recalcular_rango;\r\n--   DROP TABLE     IF EXISTS fzaest_estadisticas_dia;\r\n-- -----------------------------------------------------------------------------\r\n', '2026-06-15 07:21:13', '2026-06-15 07:21:13', 'Administrador', 'Administrador'),
  ('392', 'vistas_estadisticas', '-- =============================================================================\r\n-- Vistas de estadísticas para informes (BI) — solo lectura sobre fza_*\r\n-- =============================================================================\r\n-- Grano: día x almacén x familia x temporada.\r\n-- No alteran el esquema: CREATE OR REPLACE VIEW (idempotente). No materializan\r\n-- (MariaDB no tiene vistas materializadas); encapsulan la lógica y dejan al\r\n-- panel un SELECT simple.\r\n--\r\n-- IMPORTANTE sobre TEMPORADA:\r\n--   No es columna de fza_articulos. Es la PROPIEDAD \'TEMPORADA\'\r\n--   (fza_propiedades, NIVEL_PROP = \'COLOR\' -> propiedad de 2º nivel) cuyos\r\n--   valores viven en fza_articulos_propiedades con CODIGO_UNIDAD_ARTPROP:\r\n--     \'\'            -> valor a nivel ARTÍCULO\r\n--     ART/COLOR     -> valor a nivel COLOR  (puede variar por color)\r\n--     ART/COLOR/TALLA -> valor a nivel SKU\r\n--   Se resuelve por la clave de color derivada del SKU con SUBSTRING_INDEX,\r\n--   con fallback a nivel artículo. NO se usa vi_articulos (colapsa temporada\r\n--   a un único valor por artículo y multiplicaría filas).\r\n--   Familia SÍ es de artículo (fza_articulos.CODIGO_FAM_ART).\r\n-- =============================================================================\r\n-- 0) Resolver de temporada: una fila por (artículo, clave de nivel)\r\nCREATE OR REPLACE VIEW viest_temporada AS\r\nSELECT\r\n  p.CODIGO_ART_ART                          AS CODIGO_ART,\r\n  p.CODIGO_UNIDAD_ARTPROP                    AS CLAVE_NIVEL,\r\n  COALESCE(pv.PV, p.VALOR_LIBRE_ARTPROP)    AS TEMPORADA\r\nFROM fza_articulos_propiedades p\r\nLEFT JOIN fza_propiedades_valores pv\r\n  ON pv.ID_PV_ARTPROP = p.ID_PV_ARTPROP\r\nWHERE p.CODIGO_PROP_ARTPROP = \'TEMPORADA\';\r\n-- 1) Movimientos de almacén agregados por día\r\nCREATE OR REPLACE VIEW viest_movimientos_dia AS\r\nSELECT\r\n  DATE(m.FECHA_MOV)                              AS FECHA,\r\n  m.CODIGO_ALM_MOV                           AS CODIGO_ALMACEN,\r\n  COALESCE(a.CODIGO_FAM_ART, \'\')               AS CODIGO_FAMILIA,\r\n  COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\') AS TEMPORADA,\r\n  COUNT(*)                                       AS NUM_MOVIMIENTOS,\r\n  COALESCE(SUM(m.CANTIDAD_MOV), 0)             AS UNIDADES_MOV,\r\n  COALESCE(SUM(m.TOTAL_COSTE_MOV), 0)         AS COSTE_MOV\r\nFROM fza_movimientos_almacen m\r\nLEFT JOIN fza_articulos_skus s\r\n  ON s.CODIGO_UNIDAD_SKU = m.CODIGO_UNIDAD_MOV\r\nLEFT JOIN fza_articulos a\r\n  ON a.CODIGO_ART_ART = COALESCE(m.CODIGO_ART_MOV, s.CODIGO_ART_SKU)\r\nLEFT JOIN viest_temporada tcol\r\n  ON tcol.CODIGO_ART  = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 1)\r\n AND tcol.CLAVE_NIVEL = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 2)\r\nLEFT JOIN viest_temporada tart\r\n  ON tart.CODIGO_ART  = SUBSTRING_INDEX(m.CODIGO_UNIDAD_MOV, \'/\', 1)\r\n AND tart.CLAVE_NIVEL = \'\'\r\nWHERE m.ESACTIVO_MOV = \'S\'\r\nGROUP BY DATE(m.FECHA_MOV), m.CODIGO_ALM_MOV,\r\n         COALESCE(a.CODIGO_FAM_ART, \'\'),\r\n         COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\');\r\n-- 2) Ventas (líneas de factura) agregadas por día\r\nCREATE OR REPLACE VIEW viest_ventas_dia AS\r\nSELECT\r\n  f.FECHA_FAC                                    AS FECHA,\r\n  l.CODIGO_ALM_FACLIN                            AS CODIGO_ALMACEN,\r\n  COALESCE(a.CODIGO_FAM_ART, \'\')               AS CODIGO_FAMILIA,\r\n  COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\') AS TEMPORADA,\r\n  COUNT(*)                                       AS NUM_LINEAS_VENTA,\r\n  COALESCE(SUM(l.CANTIDAD_FACLIN), 0)         AS UNIDADES_VENTA,\r\n  COALESCE(SUM(l.TOTAL_FACLIN), 0)            AS IMPORTE_VENTA\r\nFROM fza_facturas_lineas l\r\nJOIN fza_facturas f\r\n  ON f.NUMERO_FAC = l.NUMERO_FAC_FACLIN\r\n AND f.SERIE_FAC  = l.SERIE_FAC_FACLIN\r\nLEFT JOIN fza_articulos a\r\n  ON a.CODIGO_ART_ART = l.CODIGO_ART_FACLIN\r\nLEFT JOIN viest_temporada tcol\r\n  ON tcol.CODIGO_ART  = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 1)\r\n AND tcol.CLAVE_NIVEL = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 2)\r\nLEFT JOIN viest_temporada tart\r\n  ON tart.CODIGO_ART  = SUBSTRING_INDEX(l.CODIGO_UNIDAD_FACLIN, \'/\', 1)\r\n AND tart.CLAVE_NIVEL = \'\'\r\nGROUP BY f.FECHA_FAC, l.CODIGO_ALM_FACLIN,\r\n         COALESCE(a.CODIGO_FAM_ART, \'\'),\r\n         COALESCE(tcol.TEMPORADA, tart.TEMPORADA, \'\');\r\n-- 3) Vista unificada: una fila por (día, almacén, familia, temporada) con\r\n--    todas las medidas. Es la que consultaría el panel/lab.\r\nCREATE OR REPLACE VIEW viest_dia AS\r\nSELECT\r\n  FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n  SUM(NUM_MOVIMIENTOS)  AS NUM_MOVIMIENTOS,\r\n  SUM(UNIDADES_MOV)     AS UNIDADES_MOV,\r\n  SUM(COSTE_MOV)        AS COSTE_MOV,\r\n  SUM(NUM_LINEAS_VENTA) AS NUM_LINEAS_VENTA,\r\n  SUM(UNIDADES_VENTA)   AS UNIDADES_VENTA,\r\n  SUM(IMPORTE_VENTA)    AS IMPORTE_VENTA\r\nFROM (\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n         0 AS NUM_LINEAS_VENTA, 0 AS UNIDADES_VENTA, 0 AS IMPORTE_VENTA\r\n    FROM viest_movimientos_dia\r\n  UNION ALL\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         0, 0, 0,\r\n         NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA\r\n    FROM viest_ventas_dia\r\n) u\r\nGROUP BY FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA;\r\n-- 4) Lista de temporadas (para el combo de filtro del panel)\r\nCREATE OR REPLACE VIEW viest_temporadas AS\r\nSELECT DISTINCT TEMPORADA\r\nFROM viest_temporada\r\nWHERE TEMPORADA IS NOT NULL AND TEMPORADA <> \'\';\r\n-- -----------------------------------------------------------------------------\r\n-- Ejemplo de consulta del panel (comparativa diaria de un rango):\r\n--   SELECT DATEDIFF(FECHA, :pD1) AS BUCKET, SUM(IMPORTE_VENTA) AS VALOR\r\n--     FROM viest_dia\r\n--    WHERE FECHA >= :pD1 AND FECHA <= :pD2\r\n--      AND (:pALM  = \'\' OR CODIGO_ALMACEN = :pALM)\r\n--      AND (:pFAM  = \'\' OR CODIGO_FAMILIA = :pFAM)\r\n--      AND (:pTEMP = \'\' OR TEMPORADA      = :pTEMP)\r\n--    GROUP BY BUCKET ORDER BY BUCKET;\r\n-- OJO rendimiento: una vista con GROUP BY no empuja el filtro de fecha antes\r\n-- de agregar (algoritmo TEMPTABLE), así que para el panel EN VIVO conviene\r\n-- filtrar por fecha sobre las tablas base (como hace el .pas). Estas vistas\r\n-- valen para encapsular la lógica y para el experimento fzaest_.\r\n-- -----------------------------------------------------------------------------\r\n', '2026-06-15 07:23:49', '2026-06-15 07:23:49', 'Administrador', 'Administrador'),
  ('393', NULL, 'SELECT * FROM viest_dia\r\n WHERE FECHA BETWEEN \'2026-01-01\' AND \'2026-01-31\'\r\n ORDER BY FECHA LIMIT 20;\r\nSELECT * FROM viest_temporadas;     -- ¿salen tus temporadas reales?', '2026-06-15 07:24:36', '2026-06-15 07:24:36', 'Administrador', 'Administrador'),
  ('394', NULL, '-- Ventas del mes por la vista\r\nSELECT SUM(IMPORTE_VENTA) FROM viest_dia\r\n WHERE FECHA BETWEEN \'2026-01-01\' AND \'2026-01-31\';\r\n-- Ventas del mes directo de líneas (debe coincidir)\r\nSELECT COALESCE(SUM(l.TOTAL_FACLIN),0)\r\n  FROM fza_facturas_lineas l\r\n  JOIN fza_facturas f ON f.NUMERO_FAC=l.NUMERO_FAC_FACLIN\r\n                     AND f.SERIE_FAC=l.SERIE_FAC_FACLIN\r\n WHERE f.FECHA_FAC BETWEEN \'2026-01-01\' AND \'2026-01-31\';', '2026-06-15 07:25:33', '2026-06-15 07:25:33', 'Administrador', 'Administrador'),
  ('395', 'fzaest_experimental', '-- =============================================================================\r\n-- Experimento de pre-agregado — namespace PROPIO \'fzaest_\' (NO \'fza_\')\r\n-- =============================================================================\r\n-- Para PROBAR si una tabla de acumulados acelera frente a la vista en vivo,\r\n-- sin tocar el esquema real. Todo lo de aquí usa el prefijo \'fzaest_\' (tablas)\r\n-- para diferenciarlo de \'fza_\'. Es desechable: un DROP de las fzaest_* deja la\r\n-- BBDD como estaba. Depende de vistas_estadisticas.sql (lee viest_dia).\r\n--\r\n-- Al ser un sandbox aislado, NO se siguen las convenciones de columnas de\r\n-- \'fza_\' (sufijo por tabla, etc.): nombres planos para legibilidad.\r\n-- =============================================================================\r\n-- Tabla de acumulado diario (mismo grano y medidas que viest_dia)\r\nCREATE TABLE IF NOT EXISTS fzaest_estadisticas_dia (\r\n  FECHA            date          NOT NULL,\r\n  CODIGO_ALMACEN   varchar(10)   NOT NULL,\r\n  CODIGO_FAMILIA   varchar(20)   NOT NULL DEFAULT \'\',\r\n  TEMPORADA        varchar(100)  NOT NULL DEFAULT \'\',\r\n  NUM_MOVIMIENTOS  int           NOT NULL DEFAULT 0,\r\n  UNIDADES_MOV     decimal(19,6) NOT NULL DEFAULT 0,\r\n  COSTE_MOV        decimal(19,6) NOT NULL DEFAULT 0,\r\n  NUM_LINEAS_VENTA int           NOT NULL DEFAULT 0,\r\n  UNIDADES_VENTA   decimal(19,6) NOT NULL DEFAULT 0,\r\n  IMPORTE_VENTA    decimal(19,6) NOT NULL DEFAULT 0,\r\n  INSTANTE_REFRESCO timestamp    NOT NULL DEFAULT CURRENT_TIMESTAMP\r\n                                 ON UPDATE CURRENT_TIMESTAMP,\r\n  PRIMARY KEY (FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA),\r\n  KEY IDX_FZAEST_FAM_FECHA  (CODIGO_FAMILIA, FECHA),\r\n  KEY IDX_FZAEST_TEMP_FECHA (TEMPORADA, FECHA)\r\n);\r\n-- Recálculo incremental de un rango: borra y reinserta solo esos días, de modo\r\n-- que tolera correcciones retroactivas (movimientos anulados, reclasificación\r\n-- de familia/temporada). Se alimenta de la vista unificada.\r\nDROP PROCEDURE IF EXISTS fzaest_recalcular_rango;\r\nDELIMITER //\r\nCREATE PROCEDURE fzaest_recalcular_rango(IN pD1 date, IN pD2 date)\r\nBEGIN\r\n  DELETE FROM fzaest_estadisticas_dia WHERE FECHA BETWEEN pD1 AND pD2;\r\n  INSERT INTO fzaest_estadisticas_dia\r\n    (FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n     NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n     NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA)\r\n  SELECT FECHA, CODIGO_ALMACEN, CODIGO_FAMILIA, TEMPORADA,\r\n         NUM_MOVIMIENTOS, UNIDADES_MOV, COSTE_MOV,\r\n         NUM_LINEAS_VENTA, UNIDADES_VENTA, IMPORTE_VENTA\r\n    FROM viest_dia\r\n   WHERE FECHA BETWEEN pD1 AND pD2;\r\nEND //\r\nDELIMITER ;\r\n-- -----------------------------------------------------------------------------\r\n-- Uso / benchmark:\r\n--   CALL fzaest_recalcular_rango(\'2020-01-01\', CURDATE());   -- carga inicial\r\n--   -- Comparar tiempos del MISMO rango largo:\r\n--   --   en vivo:        SELECT ... FROM viest_dia      WHERE ...\r\n--   --   pre-agregado:   SELECT ... FROM fzaest_estadisticas_dia  WHERE ...\r\n-- Limpieza total del experimento:\r\n--   DROP PROCEDURE IF EXISTS fzaest_recalcular_rango;\r\n--   DROP TABLE     IF EXISTS fzaest_estadisticas_dia;\r\n-- -----------------------------------------------------------------------------\r\n', '2026-06-15 07:26:40', '2026-06-15 07:26:40', 'Administrador', 'Administrador'),
  ('396', 'verifactu_registros_firmados', '-- =============================================================================\r\n-- Registros VERI*FACTU / NO VERI*FACTU firmados\r\n-- =============================================================================\r\n-- Anade almacenamiento del XML oficial firmado XAdES en eventos y registros\r\n-- de facturacion. No modifica factuzam_original.sql.\r\n-- Idempotente: cada columna se crea solo si no existe.\r\n-- =============================================================================\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_eventos\'\r\n     AND COLUMN_NAME  = \'REGISTRO_XML_LOG\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_verifactu_eventos\r\n     ADD COLUMN REGISTRO_XML_LOG longtext NULL DEFAULT NULL\r\n     AFTER SERIE_FAC_LOG\',\r\n  \'SELECT \'\'REGISTRO_XML_LOG ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_eventos\'\r\n     AND COLUMN_NAME  = \'FIRMA_XADES_LOG\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_verifactu_eventos\r\n     ADD COLUMN FIRMA_XADES_LOG longtext NULL DEFAULT NULL\r\n     AFTER REGISTRO_XML_LOG\',\r\n  \'SELECT \'\'FIRMA_XADES_LOG ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_eventos\'\r\n     AND COLUMN_NAME  = \'SERIE_CERTIFICADO_LOG\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_verifactu_eventos\r\n     ADD COLUMN SERIE_CERTIFICADO_LOG varchar(128) NULL DEFAULT NULL\r\n     AFTER FIRMA_XADES_LOG\',\r\n  \'SELECT \'\'SERIE_CERTIFICADO_LOG ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_eventos\'\r\n     AND COLUMN_NAME  = \'TITULAR_CERTIFICADO_LOG\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_verifactu_eventos\r\n     ADD COLUMN TITULAR_CERTIFICADO_LOG varchar(1000) NULL DEFAULT NULL\r\n     AFTER SERIE_CERTIFICADO_LOG\',\r\n  \'SELECT \'\'TITULAR_CERTIFICADO_LOG ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_verifactu_eventos\'\r\n     AND COLUMN_NAME  = \'HUELLA_CERTIFICADO_LOG\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_verifactu_eventos\r\n     ADD COLUMN HUELLA_CERTIFICADO_LOG char(40) NULL DEFAULT NULL\r\n     AFTER TITULAR_CERTIFICADO_LOG\',\r\n  \'SELECT \'\'HUELLA_CERTIFICADO_LOG ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas_consolidaciones\'\r\n     AND COLUMN_NAME  = \'REGISTRO_XML_FACCON\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas_consolidaciones\r\n     ADD COLUMN REGISTRO_XML_FACCON longtext NULL DEFAULT NULL\r\n     AFTER PETICION_COMPLETA_FACCON\',\r\n  \'SELECT \'\'REGISTRO_XML_FACCON ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas_consolidaciones\'\r\n     AND COLUMN_NAME  = \'FIRMA_DIGITAL_FACCON\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas_consolidaciones\r\n     ADD COLUMN FIRMA_DIGITAL_FACCON longtext NULL DEFAULT NULL\r\n     AFTER REGISTRO_XML_FACCON\',\r\n  \'SELECT \'\'FIRMA_DIGITAL_FACCON ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas_consolidaciones\'\r\n     AND COLUMN_NAME  = \'SERIE_CERTIFICADO_FACCON\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas_consolidaciones\r\n     ADD COLUMN SERIE_CERTIFICADO_FACCON varchar(128) NULL DEFAULT NULL\r\n     AFTER FIRMA_DIGITAL_FACCON\',\r\n  \'SELECT \'\'SERIE_CERTIFICADO_FACCON ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas_consolidaciones\'\r\n     AND COLUMN_NAME  = \'TITULAR_CERTIFICADO_FACCON\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas_consolidaciones\r\n     ADD COLUMN TITULAR_CERTIFICADO_FACCON varchar(1000) NULL DEFAULT NULL\r\n     AFTER SERIE_CERTIFICADO_FACCON\',\r\n  \'SELECT \'\'TITULAR_CERTIFICADO_FACCON ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas_consolidaciones\'\r\n     AND COLUMN_NAME  = \'HUELLA_CERTIFICADO_FACCON\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas_consolidaciones\r\n     ADD COLUMN HUELLA_CERTIFICADO_FACCON char(40) NULL DEFAULT NULL\r\n     AFTER TITULAR_CERTIFICADO_FACCON\',\r\n  \'SELECT \'\'HUELLA_CERTIFICADO_FACCON ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n', '2026-06-15 19:14:14', '2026-06-15 19:14:14', 'Administrador', 'Administrador'),
  ('397', 'facturae_dir3_clientes', '-- =============================================================================\r\n-- Anade parametros DIR3 Facturae a clientes y facturas\r\n-- =============================================================================\r\n-- FACe valida los tres centros administrativos del receptor publico:\r\n-- oficina contable, organo gestor y unidad tramitadora.\r\n--\r\n-- Cliente: valores por defecto para nuevos eDoc.\r\n-- Factura: foto usada en esa factura concreta.\r\n--\r\n-- Idempotente: se puede ejecutar varias veces. Cada columna se anade solo si\r\n-- no existe y las vistas se recrean para exponer los campos nuevos.\r\n-- =============================================================================\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_clientes\'\r\n     AND COLUMN_NAME  = \'CODIGO_OFICINA_CONTABLE_CLI\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_clientes\r\n     ADD COLUMN CODIGO_OFICINA_CONTABLE_CLI varchar(10) NULL DEFAULT NULL\r\n     AFTER NOMBRE_PAI_CLI\',\r\n  \'SELECT \'\'CODIGO_OFICINA_CONTABLE_CLI ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_clientes\'\r\n     AND COLUMN_NAME  = \'CODIGO_ORGANO_GESTOR_CLI\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_clientes\r\n     ADD COLUMN CODIGO_ORGANO_GESTOR_CLI varchar(10) NULL DEFAULT NULL\r\n     AFTER CODIGO_OFICINA_CONTABLE_CLI\',\r\n  \'SELECT \'\'CODIGO_ORGANO_GESTOR_CLI ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_clientes\'\r\n     AND COLUMN_NAME  = \'CODIGO_UNIDAD_TRAMITADORA_CLI\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_clientes\r\n     ADD COLUMN CODIGO_UNIDAD_TRAMITADORA_CLI varchar(10) NULL DEFAULT NULL\r\n     AFTER CODIGO_ORGANO_GESTOR_CLI\',\r\n  \'SELECT \'\'CODIGO_UNIDAD_TRAMITADORA_CLI ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas\'\r\n     AND COLUMN_NAME  = \'CODIGO_OFICINA_CONTABLE_FAC\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas\r\n     ADD COLUMN CODIGO_OFICINA_CONTABLE_FAC varchar(10) NULL DEFAULT NULL\r\n     AFTER NOMBRE_PAI_CLIENTE_FAC\',\r\n  \'SELECT \'\'CODIGO_OFICINA_CONTABLE_FAC ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas\'\r\n     AND COLUMN_NAME  = \'CODIGO_ORGANO_GESTOR_FAC\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas\r\n     ADD COLUMN CODIGO_ORGANO_GESTOR_FAC varchar(10) NULL DEFAULT NULL\r\n     AFTER CODIGO_OFICINA_CONTABLE_FAC\',\r\n  \'SELECT \'\'CODIGO_ORGANO_GESTOR_FAC ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_facturas\'\r\n     AND COLUMN_NAME  = \'CODIGO_UNIDAD_TRAMITADORA_FAC\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_facturas\r\n     ADD COLUMN CODIGO_UNIDAD_TRAMITADORA_FAC varchar(10) NULL DEFAULT NULL\r\n     AFTER CODIGO_ORGANO_GESTOR_FAC\',\r\n  \'SELECT \'\'CODIGO_UNIDAD_TRAMITADORA_FAC ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nUPDATE fza_facturas f\r\n  JOIN fza_clientes c\r\n    ON c.CODIGO_CLI_CLI = f.CODIGO_CLI_FAC\r\n   SET f.CODIGO_OFICINA_CONTABLE_FAC =\r\n       COALESCE(NULLIF(f.CODIGO_OFICINA_CONTABLE_FAC, \'\'),\r\n                c.CODIGO_OFICINA_CONTABLE_CLI),\r\n       f.CODIGO_ORGANO_GESTOR_FAC =\r\n       COALESCE(NULLIF(f.CODIGO_ORGANO_GESTOR_FAC, \'\'),\r\n                c.CODIGO_ORGANO_GESTOR_CLI),\r\n       f.CODIGO_UNIDAD_TRAMITADORA_FAC =\r\n       COALESCE(NULLIF(f.CODIGO_UNIDAD_TRAMITADORA_FAC, \'\'),\r\n                c.CODIGO_UNIDAD_TRAMITADORA_CLI)\r\n WHERE (f.CODIGO_OFICINA_CONTABLE_FAC IS NULL\r\n        OR f.CODIGO_OFICINA_CONTABLE_FAC = \'\'\r\n        OR f.CODIGO_ORGANO_GESTOR_FAC IS NULL\r\n        OR f.CODIGO_ORGANO_GESTOR_FAC = \'\'\r\n        OR f.CODIGO_UNIDAD_TRAMITADORA_FAC IS NULL\r\n        OR f.CODIGO_UNIDAD_TRAMITADORA_FAC = \'\')\r\n   AND (c.CODIGO_OFICINA_CONTABLE_CLI IS NOT NULL\r\n        OR c.CODIGO_ORGANO_GESTOR_CLI IS NOT NULL\r\n        OR c.CODIGO_UNIDAD_TRAMITADORA_CLI IS NOT NULL);\r\n\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW vi_clientes AS\r\nSELECT c.*\r\n  FROM fza_clientes c\r\n ORDER BY c.ORDEN_CLI;\r\n\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW vi_cli_busquedas AS\r\nSELECT c.*\r\n  FROM fza_clientes c\r\n WHERE c.ESACTIVO_CLI = \'S\'\r\n ORDER BY c.CODIGO_CLI_CLI DESC;\r\n\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW vi_facturas AS\r\nSELECT f.*,\r\n       fp.DESCRIPCION_FORMA_PAGO_FP,\r\n       fp.ESCONTADO_FORMA_PAGO_FP,\r\n       (\r\n         SELECT GROUP_CONCAT(\r\n                  \' \',\r\n                  DATE_FORMAT(r.FECHA_VENCIMIENTO_RECIBO_REC, \'%d/%m/%Y\'),\r\n                  \'=> \',\r\n                  FORMAT(r.EUROS_RECIBO_REC, 2),\r\n                  \'€\'\r\n                  SEPARATOR \',\'\r\n                )\r\n           FROM fza_recibos r\r\n          WHERE r.NUMERO_FAC_REC = f.NUMERO_FAC\r\n            AND r.SERIE_FAC_REC = f.SERIE_FAC\r\n       ) AS VENCIMIENTOS_RECIBOS,\r\n       emp.IBAN_EMP,\r\n       cli.IBAN_CLI,\r\n       fp.ESVERBANCOEMPRESA_FORMA_PAGO_FP,\r\n       c.ID_FACCON,\r\n       c.REQUEST_ID_CONSOLIDACION_FACCON,\r\n       c.ISSUER_IRS_ID_CONSOLIDACION_FACCON,\r\n       c.ISSUED_TIME_FACCON,\r\n       c.CHAIN_NUMBER_FACCON,\r\n       c.CHAIN_HASH_FACCON,\r\n       c.VERIFACTU_URL_FACCON,\r\n       c.QRCODE_BASE64_FACCON,\r\n       c.QRCODE_PNG_FACCON,\r\n       c.FECHA_PROCESAMIENTO_FACCON,\r\n       c.ESTADO_FACCON\r\n  FROM fza_facturas f\r\n  LEFT JOIN fza_formas_pago fp\r\n    ON f.FORMA_PAGO_FAC = fp.CODIGO_FP_FP\r\n  LEFT JOIN fza_empresas emp\r\n    ON f.CODIGO_EMP_FAC = emp.CODIGO_EMP_EMP\r\n  LEFT JOIN fza_clientes cli\r\n    ON f.CODIGO_CLI_FAC = cli.CODIGO_CLI_CLI\r\n  LEFT JOIN fza_facturas_consolidaciones c\r\n    ON c.SERIE_FAC_FACCON = f.SERIE_FAC\r\n   AND c.NUMERO_FAC_FACCON = f.NUMERO_FAC\r\n ORDER BY f.FECHA_FAC DESC;\r\n\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW vi_facturas_normales AS\r\nSELECT *\r\n  FROM vi_facturas\r\n WHERE TIPO_FAC = \'NORMAL\';\r\n\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW vi_facturas_simplificadas AS\r\nSELECT *\r\n  FROM vi_facturas\r\n WHERE TIPO_FAC = \'SIMPLIFICADA\';\r\n', '2026-06-15 21:49:19', '2026-06-15 21:49:19', 'Administrador', 'Administrador'),
