emp.`CODIGO_EMP_EMP` = ses.`CODIGO_EMP_SES`\r\nLEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = ses.`CODIGO_PRV_SES`;\r\n\r\nCREATE OR REPLACE VIEW `vi_albaranes_compra_cab_print` AS\r\nSELECT\r\n  alb.`SERIE_ALBC`,\r\n  alb.`NUMERO_ALBC`,\r\n  alb.`FECHA_ALBC`,\r\n  alb.`ESTADO_ALBC`,\r\n  alb.`REF_PROVEEDOR_ALBC`,\r\n  alb.`COMENTARIOS_ALBC`,\r\n  alb.`OBSERVACIONES_ALBC`,\r\n  alb.`CODIGO_EMP_ALBC`,\r\n  emp.`FORMATO_DOCUMENTO_EMP`,\r\n  CASE WHEN TRIM(COALESCE(alb.`SERIE_ALBC`, \'\')) = \'\' THEN TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\')) WHEN TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\')) = \'\' THEN TRIM(COALESCE(alb.`SERIE_ALBC`, \'\')) WHEN NOT (INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'serie\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'numerodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'númerodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrofactura\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrodoc\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'numero\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'número\') > 0) THEN CONCAT(TRIM(COALESCE(alb.`SERIE_ALBC`, \'\')), \'.\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))) ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\'), \'NroDocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'nrodocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NRODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NumeroDocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'numerodocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NUMERODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NúmeroDocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'númerodocumento\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NÚMERODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NroFactura\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'nrofactura\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NROFACTURA\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NroDoc\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'nrodoc\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NRODOC\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'Numero\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'numero\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NUMERO\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'Número\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'número\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'NÚMERO\', TRIM(COALESCE(alb.`NUMERO_ALBC`, \'\'))), \'Serie\', TRIM(COALESCE(alb.`SERIE_ALBC`, \'\'))), \'serie\', TRIM(COALESCE(alb.`SERIE_ALBC`, \'\'))), \'SERIE\', TRIM(COALESCE(alb.`SERIE_ALBC`, \'\'))) END AS `DOCUMENTO_FORMATO`,\r\n  emp.`RAZON_SOCIAL_EMP`,\r\n  emp.`DIRECCION1_EMP`,\r\n  emp.`CODIGO_POSTAL_EMP`,\r\n  emp.`POBLACION_EMP`,\r\n  emp.`PROVINCIA_EMP`,\r\n  emp.`NIF_EMP`        AS `CIF_EMP`,\r\n  emp.`MOVIL_EMP`      AS `TELEFONO1_EMP`,\r\n  alb.`CODIGO_PRV_ALBC`,\r\n  prv.`RAZON_SOCIAL_PRV`,\r\n  prv.`DIRECCION1_PRV`,\r\n  prv.`CODIGO_POSTAL_PRV`,\r\n  prv.`POBLACION_PRV`,\r\n  prv.`PROVINCIA_PRV`,\r\n  prv.`NIF_PRV`        AS `CIF_PRV`,\r\n  COALESCE(prv.`TELEFONO_PRV`, prv.`MOVIL_PRV`) AS `TELEFONO1_PRV`,\r\n  alb.`CODIGO_ALM_ALBC`,\r\n  alm.`NOMBRE_ALM_ALM`  AS `NOMBRE_ALM_ALBC`,\r\n  alm.`DIRECCION_ALM`   AS `DIRECCION_ALM_ALBC`,\r\n  alm.`CODIGO_POSTAL_ALM` AS `CODIGO_POSTAL_ALM_ALBC`,\r\n  alm.`POBLACION_ALM`   AS `POBLACION_ALM_ALBC`,\r\n  alm.`PROVINCIA_ALM`   AS `PROVINCIA_ALM_ALBC`,\r\n  alm.`TELEFONO_ALM`    AS `TELEFONO_ALM_ALBC`,\r\n  alm.`EMAIL_ALM`       AS `EMAIL_ALM_ALBC`,\r\n  alb.`CODIGO_IVA_ALBC`,\r\n  alb.`ESIVA_RECARGO_COMPRAS_ALBC`,\r\n  alb.`PORCENTAJE_IVAN_ALBC`,\r\n  alb.`TOTAL_BASEI_IVAN_ALBC`,\r\n  alb.`TOTAL_IVAN_ALBC`,\r\n  alb.`PORCENTAJE_REN_ALBC`,\r\n  alb.`TOTAL_REN_ALBC`,\r\n  alb.`PORCENTAJE_IVAR_ALBC`,\r\n  alb.`TOTAL_BASEI_IVAR_ALBC`,\r\n  alb.`TOTAL_IVAR_ALBC`,\r\n  alb.`PORCENTAJE_RER_ALBC`,\r\n  alb.`TOTAL_RER_ALBC`,\r\n  alb.`PORCENTAJE_IVAS_ALBC`,\r\n  alb.`TOTAL_BASEI_IVAS_ALBC`,\r\n  alb.`TOTAL_IVAS_ALBC`,\r\n  alb.`PORCENTAJE_RES_ALBC`,\r\n  alb.`TOTAL_RES_ALBC`,\r\n  alb.`PORCENTAJE_IVAE_ALBC`,\r\n  alb.`TOTAL_BASEI_IVAE_ALBC`,\r\n  alb.`TOTAL_IVAE_ALBC`,\r\n  alb.`PORCENTAJE_REE_ALBC`,\r\n  alb.`TOTAL_REE_ALBC`,\r\n  alb.`PORCENTAJE_RETENCION_ALBC`,\r\n  alb.`TOTAL_RETENCION_ALBC`,\r\n  alb.`TOTAL_BASES_ALBC`,\r\n  alb.`TOTAL_IMPUESTOS_ALBC`,\r\n  alb.`TOTAL_LIQUIDO_ALBC`,\r\n  alb.`INSTANTE_ALTA`,\r\n  alb.`USUARIO_ALTA`,\r\n  (SELECT COALESCE(SUM(`CANTIDAD_ALBCLIN`), 0)\r\n     FROM `fza_albaranes_compra_lineas` lin\r\n    WHERE lin.`SERIE_ALBC_ALBCLIN`  = alb.`SERIE_ALBC`\r\n      AND lin.`NUMERO_ALBC_ALBCLIN` = alb.`NUMERO_ALBC`) AS `TOTAL_UNIDADES_SES`,\r\n  (SELECT COALESCE(SUM(`TOTAL_ALBCLIN`), 0)\r\n     FROM `fza_albaranes_compra_lineas` lin\r\n    WHERE lin.`SERIE_ALBC_ALBCLIN`  = alb.`SERIE_ALBC`\r\n      AND lin.`NUMERO_ALBC_ALBCLIN` = alb.`NUMERO_ALBC`) AS `TOTAL_LINEAS_SES`,\r\n  (SELECT COUNT(*)\r\n     FROM `fza_albaranes_compra_lineas` lin\r\n    WHERE lin.`SERIE_ALBC_ALBCLIN`  = alb.`SERIE_ALBC`\r\n      AND lin.`NUMERO_ALBC_ALBCLIN` = alb.`NUMERO_ALBC`) AS `NUM_LINEAS_SES`\r\nFROM `fza_albaranes_compra` alb\r\nLEFT JOIN `fza_empresas`     emp ON emp.`CODIGO_EMP_EMP` = alb.`CODIGO_EMP_ALBC`\r\nLEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = alb.`CODIGO_PRV_ALBC`\r\nLEFT JOIN `fza_almacenes`    alm ON alm.`CODIGO_ALM_ALM` = alb.`CODIGO_ALM_ALBC`;\r\n\r\nCREATE OR REPLACE VIEW `vi_devoluciones_compra_cab_print` AS\r\nSELECT\r\n  alb.`SERIE_DEVC`,\r\n  alb.`NUMERO_DEVC`,\r\n  alb.`FECHA_DEVC`,\r\n  alb.`ESTADO_DEVC`,\r\n  alb.`REF_PROVEEDOR_DEVC`,\r\n  alb.`COMENTARIOS_DEVC`,\r\n  alb.`OBSERVACIONES_DEVC`,\r\n  alb.`CODIGO_EMP_DEVC`,\r\n  emp.`FORMATO_DOCUMENTO_EMP`,\r\n  CASE WHEN TRIM(COALESCE(alb.`SERIE_DEVC`, \'\')) = \'\' THEN TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\')) WHEN TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\')) = \'\' THEN TRIM(COALESCE(alb.`SERIE_DEVC`, \'\')) WHEN NOT (INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'serie\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'numerodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'númerodocumento\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrofactura\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'nrodoc\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'numero\') > 0 OR INSTR(LOWER(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\')), \'número\') > 0) THEN CONCAT(TRIM(COALESCE(alb.`SERIE_DEVC`, \'\')), \'.\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))) ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(TRIM(COALESCE(emp.`FORMATO_DOCUMENTO_EMP`, \'\')), \'\'), \'Serie.NroDocumento\'), \'NroDocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'nrodocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NRODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NumeroDocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'numerodocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NUMERODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NúmeroDocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'númerodocumento\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NÚMERODOCUMENTO\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NroFactura\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'nrofactura\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NROFACTURA\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NroDoc\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'nrodoc\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NRODOC\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'Numero\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'numero\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NUMERO\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'Número\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'número\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'NÚMERO\', TRIM(COALESCE(alb.`NUMERO_DEVC`, \'\'))), \'Serie\', TRIM(COALESCE(alb.`SERIE_DEVC`, \'\'))), \'serie\', TRIM(COALESCE(alb.`SERIE_DEVC`, \'\'))), \'SERIE\', TRIM(COALESCE(alb.`SERIE_DEVC`, \'\'))) END AS `DOCUMENTO_FORMATO`,\r\n  emp.`RAZON_SOCIAL_EMP`,\r\n  emp.`DIRECCION1_EMP`,\r\n  emp.`CODIGO_POSTAL_EMP`,\r\n  emp.`POBLACION_EMP`,\r\n  emp.`PROVINCIA_EMP`,\r\n  emp.`NIF_EMP`        AS `CIF_EMP`,\r\n  emp.`MOVIL_EMP`      AS `TELEFONO1_EMP`,\r\n  alb.`CODIGO_PRV_DEVC`,\r\n  prv.`RAZON_SOCIAL_PRV`,\r\n  prv.`DIRECCION1_PRV`,\r\n  prv.`CODIGO_POSTAL_PRV`,\r\n  prv.`POBLACION_PRV`,\r\n  prv.`PROVINCIA_PRV`,\r\n  prv.`NIF_PRV`        AS `CIF_PRV`,\r\n  COALESCE(prv.`TELEFONO_PRV`, prv.`MOVIL_PRV`) AS `TELEFONO1_PRV`,\r\n  alb.`CODIGO_ALM_DEVC`,\r\n  alm.`NOMBRE_ALM_ALM`  AS `NOMBRE_ALM_DEVC`,\r\n  alm.`DIRECCION_ALM`   AS `DIRECCION_ALM_DEVC`,\r\n  alm.`CODIGO_POSTAL_ALM` AS `CODIGO_POSTAL_ALM_DEVC`,\r\n  alm.`POBLACION_ALM`   AS `POBLACION_ALM_DEVC`,\r\n  alm.`PROVINCIA_ALM`   AS `PROVINCIA_ALM_DEVC`,\r\n  alm.`TELEFONO_ALM`    AS `TELEFONO_ALM_DEVC`,\r\n  alm.`EMAIL_ALM`       AS `EMAIL_ALM_DEVC`,\r\n  alb.`CODIGO_IVA_DEVC`,\r\n  alb.`ESIVA_RECARGO_COMPRAS_DEVC`,\r\n  alb.`PORCENTAJE_IVAN_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAN_DEVC`,\r\n  alb.`TOTAL_IVAN_DEVC`,\r\n  alb.`PORCENTAJE_REN_DEVC`,\r\n  alb.`TOTAL_REN_DEVC`,\r\n  alb.`PORCENTAJE_IVAR_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAR_DEVC`,\r\n  alb.`TOTAL_IVAR_DEVC`,\r\n  alb.`PORCENTAJE_RER_DEVC`,\r\n  alb.`TOTAL_RER_DEVC`,\r\n  alb.`PORCENTAJE_IVAS_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAS_DEVC`,\r\n  alb.`TOTAL_IVAS_DEVC`,\r\n  alb.`PORCENTAJE_RES_DEVC`,\r\n  alb.`TOTAL_RES_DEVC`,\r\n  alb.`PORCENTAJE_IVAE_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAE_DEVC`,\r\n  alb.`TOTAL_IVAE_DEVC`,\r\n  alb.`PORCENTAJE_REE_DEVC`,\r\n  alb.`TOTAL_REE_DEVC`,\r\n  alb.`PORCENTAJE_RETENCION_DEVC`,\r\n  alb.`TOTAL_RETENCION_DEVC`,\r\n  alb.`TOTAL_BASES_DEVC`,\r\n  alb.`TOTAL_IMPUESTOS_DEVC`,\r\n  alb.`TOTAL_LIQUIDO_DEVC`,\r\n  alb.`INSTANTE_ALTA`,\r\n  alb.`USUARIO_ALTA`,\r\n  (SELECT COALESCE(SUM(`CANTIDAD_DEVCLIN`), 0)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_UNIDADES_SES`,\r\n  (SELECT COALESCE(SUM(`TOTAL_DEVCLIN`), 0)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_LINEAS_SES`,\r\n  (SELECT COUNT(*)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `NUM_LINEAS_SES`\r\nFROM `fza_devoluciones_compra` alb\r\nLEFT JOIN `fza_empresas`     emp ON emp.`CODIGO_EMP_EMP` = alb.`CODIGO_EMP_DEVC`\r\nLEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = alb.`CODIGO_PRV_DEVC`\r\nLEFT JOIN `fza_almacenes`    alm ON alm.`CODIGO_ALM_ALM` = alb.`CODIGO_ALM_DEVC`;\r\n', '2026-06-21 17:26:38', '2026-06-21 17:26:38', 'Administrador', 'Administrador'),
  ('449', 'vi_devoluciones_compra_print', '-- =============================================================================\r\n-- Vistas para la impresion del devolucion de compra\r\n-- Analogo a vi_compras_sesiones_*_print pero contra el modelo de devoluciones\r\n-- de compra (cabecera + lineas; sin tabla de celdas separada — los SKUs\r\n-- viven directamente en fza_devoluciones_compra_lineas y la talla se deduce\r\n-- del atributo CO/TAL del SKU).\r\n--\r\n-- Script idempotente: CREATE OR REPLACE, se puede aplicar repetidamente.\r\n-- =============================================================================\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 1. Cabecera enriquecida (empresa + proveedor + almacen destino + totales)\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE VIEW `vi_devoluciones_compra_cab_print` AS\r\nSELECT\r\n  alb.`SERIE_DEVC`,\r\n  alb.`NUMERO_DEVC`,\r\n  alb.`FECHA_DEVC`,\r\n  alb.`ESTADO_DEVC`,\r\n  alb.`REF_PROVEEDOR_DEVC`,\r\n  alb.`COMENTARIOS_DEVC`,\r\n  alb.`OBSERVACIONES_DEVC`,\r\n  alb.`CODIGO_EMP_DEVC`,\r\n  emp.`RAZON_SOCIAL_EMP`,\r\n  emp.`DIRECCION1_EMP`,\r\n  emp.`CODIGO_POSTAL_EMP`,\r\n  emp.`POBLACION_EMP`,\r\n  emp.`PROVINCIA_EMP`,\r\n  emp.`NIF_EMP`        AS `CIF_EMP`,\r\n  emp.`MOVIL_EMP`      AS `TELEFONO1_EMP`,\r\n  alb.`CODIGO_PRV_DEVC`,\r\n  prv.`RAZON_SOCIAL_PRV`,\r\n  prv.`DIRECCION1_PRV`,\r\n  prv.`CODIGO_POSTAL_PRV`,\r\n  prv.`POBLACION_PRV`,\r\n  prv.`PROVINCIA_PRV`,\r\n  prv.`NIF_PRV`        AS `CIF_PRV`,\r\n  COALESCE(prv.`TELEFONO_PRV`, prv.`MOVIL_PRV`) AS `TELEFONO1_PRV`,\r\n  -- Almacen destino: el codigo vive en la cabecera (CODIGO_ALM_DEVC) y\r\n  -- los datos descriptivos se resuelven via JOIN a fza_almacenes. No\r\n  -- snapshoteamos como con empresa/proveedor: si cambia la direccion\r\n  -- del almacen, los devoluciones historicos mostraran la actual.\r\n  alb.`CODIGO_ALM_DEVC`,\r\n  alm.`NOMBRE_ALM_ALM`  AS `NOMBRE_ALM_DEVC`,\r\n  alm.`DIRECCION_ALM`   AS `DIRECCION_ALM_DEVC`,\r\n  alm.`CODIGO_POSTAL_ALM` AS `CODIGO_POSTAL_ALM_DEVC`,\r\n  alm.`POBLACION_ALM`   AS `POBLACION_ALM_DEVC`,\r\n  alm.`PROVINCIA_ALM`   AS `PROVINCIA_ALM_DEVC`,\r\n  alm.`TELEFONO_ALM`    AS `TELEFONO_ALM_DEVC`,\r\n  alm.`EMAIL_ALM`       AS `EMAIL_ALM_DEVC`,\r\n  alb.`CODIGO_IVA_DEVC`,\r\n  alb.`ESIVA_RECARGO_COMPRAS_DEVC`,\r\n  alb.`PORCENTAJE_IVAN_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAN_DEVC`,\r\n  alb.`TOTAL_IVAN_DEVC`,\r\n  alb.`PORCENTAJE_REN_DEVC`,\r\n  alb.`TOTAL_REN_DEVC`,\r\n  alb.`PORCENTAJE_IVAR_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAR_DEVC`,\r\n  alb.`TOTAL_IVAR_DEVC`,\r\n  alb.`PORCENTAJE_RER_DEVC`,\r\n  alb.`TOTAL_RER_DEVC`,\r\n  alb.`PORCENTAJE_IVAS_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAS_DEVC`,\r\n  alb.`TOTAL_IVAS_DEVC`,\r\n  alb.`PORCENTAJE_RES_DEVC`,\r\n  alb.`TOTAL_RES_DEVC`,\r\n  alb.`PORCENTAJE_IVAE_DEVC`,\r\n  alb.`TOTAL_BASEI_IVAE_DEVC`,\r\n  alb.`TOTAL_IVAE_DEVC`,\r\n  alb.`PORCENTAJE_REE_DEVC`,\r\n  alb.`TOTAL_REE_DEVC`,\r\n  alb.`PORCENTAJE_RETENCION_DEVC`,\r\n  alb.`TOTAL_RETENCION_DEVC`,\r\n  alb.`TOTAL_BASES_DEVC`,\r\n  alb.`TOTAL_IMPUESTOS_DEVC`,\r\n  alb.`TOTAL_LIQUIDO_DEVC`,\r\n  alb.`INSTANTE_ALTA`,\r\n  alb.`USUARIO_ALTA`,\r\n  -- Agregados de las lineas\r\n  (SELECT COALESCE(SUM(`CANTIDAD_DEVCLIN`), 0)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_UNIDADES_SES`,\r\n  (SELECT COALESCE(SUM(`TOTAL_DEVCLIN`), 0)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `TOTAL_LINEAS_SES`,\r\n  (SELECT COUNT(*)\r\n     FROM `fza_devoluciones_compra_lineas` lin\r\n    WHERE lin.`SERIE_DEVC_DEVCLIN`  = alb.`SERIE_DEVC`\r\n      AND lin.`NUMERO_DEVC_DEVCLIN` = alb.`NUMERO_DEVC`) AS `NUM_LINEAS_SES`\r\nFROM `fza_devoluciones_compra` alb\r\nLEFT JOIN `fza_empresas`     emp ON emp.`CODIGO_EMP_EMP` = alb.`CODIGO_EMP_DEVC`\r\nLEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = alb.`CODIGO_PRV_DEVC`\r\nLEFT JOIN `fza_almacenes`    alm ON alm.`CODIGO_ALM_ALM` = alb.`CODIGO_ALM_DEVC`;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 2. Lineas con T01..T20 pivotadas por talla\r\n-- ---------------------------------------------------------------------------\r\n-- Como en devolucion cada linea ya es un SKU, agrupamos por (articulo, color\r\n-- derivado del SKU, ID_AC_PIVOT, almacen destino) y sumamos\r\n-- CANTIDAD_DEVCLIN en la posicion correspondiente del conjunto pivot. La\r\n-- talla del SKU se obtiene de fza_atributos_sku (atributo con\r\n-- ID_VA_AV=\'TAL\'). El color se obtiene del mismo modo (atributo con\r\n-- ID_VA_AV=\'CO\' -> CODIGO_ATB/NOMBRE_ATB del atributo basico, o fallback\r\n-- al segundo segmento del SKU).\r\n-- IMPORTANTE: el color forma parte de la clave de agrupacion. Sin el, las\r\n-- lineas de varios colores del mismo articulo + sistema de tallas se\r\n-- colapsaban en una unica fila y los SUM por talla sumaban todas las\r\n-- cantidades juntas (impresion horizontal mostraba 1 fila con la suma de\r\n-- los 4 colores). El GROUP BY incluye CODIGO_ATB_COLOR + NOMBRE_COLOR\r\n-- (color via atributo basico) y el segmento medio del SKU (fallback para\r\n-- SKUs sin atributo CO).\r\n-- Tambien forma parte de la clave el CODIGO_ALMACEN_DEVCLIN: en devoluciones\r\n-- agrupados (mezclan varios almacenes destino aunque la cabecera tenga\r\n-- uno principal) las lineas de un mismo articulo en distintos almacenes\r\n-- aparecen como filas separadas, una por almacen, para que el .frx pueda\r\n-- imprimir junto a cada linea el almacen al que va destinada.\r\nCREATE OR REPLACE VIEW `vi_devoluciones_compra_lin_print` AS\r\nWITH `pos_acd` AS (\r\n  SELECT\r\n    `ID_AC_ACD` AS `ID_AC`,\r\n    `ID_AV_ACD` AS `ID_AV`,\r\n    ROW_NUMBER() OVER (\r\n      PARTITION BY `ID_AC_ACD`\r\n      ORDER BY `ORDEN_ACD`, `ID_AV_ACD`\r\n    ) AS `POSICION`\r\n  FROM `fza_atributos_conjuntos_det`\r\n),\r\n`sku_talla` AS (\r\n  SELECT\r\n    sa.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,\r\n    sa.`ID_AV_SA`             AS `ID_AV_TALLA`\r\n  FROM `fza_atributos_sku` sa\r\n  JOIN `fza_atributos_valores` av\r\n    ON av.`ID_AV` = sa.`ID_AV_SA`\r\n   AND av.`ID_VA_AV` = \'TAL\'\r\n),\r\n`sku_color` AS (\r\n  SELECT\r\n    sa.`CODIGO_UNIDAD_SKU_SA` AS `CODIGO_UNIDAD`,\r\n    atb.`CODIGO_ATB`          AS `CODIGO_ATB_COLOR`,\r\n    atb.`NOMBRE_ATB`          AS `NOMBRE_COLOR`\r\n  FROM `fza_atributos_sku` sa\r\n  JOIN `fza_atributos_valores` av\r\n    ON av.`ID_AV` = sa.`ID_AV_SA`\r\n   AND av.`ID_VA_AV` = \'CO\'\r\n  LEFT JOIN `fza_atributos_basicos` atb\r\n    ON atb.`ID_ATB` = av.`ID_ATB_AV`\r\n)\r\nSELECT\r\n  L.`SERIE_DEVC_DEVCLIN`            AS `SERIE_DEVC`,\r\n  L.`NUMERO_DEVC_DEVCLIN`           AS `NUMERO_DEVC`,\r\n  MIN(L.`LINEA_DEVCLIN`)            AS `LINEA_DEVC`,\r\n  L.`CODIGO_ART_DEVCLIN`            AS `CODIGO_ART`,\r\n  COALESCE(MIN(L.`REF_PRV_DEVCLIN`), \'\') AS `REF_PRV`,\r\n  MIN(L.`DESCRIPCION_ARTICULO_DEVCLIN`) AS `DESCRIPCION`,\r\n  COALESCE(MIN(sc.`NOMBRE_COLOR`),\r\n           SUBSTRING_INDEX(SUBSTRING_INDEX(MIN(L.`CODIGO_UNIDAD_DEVCLIN`), \'/\', 2), \'/\', -1),\r\n           \'\')                      AS `COLOR_TEXTO`,\r\n  COALESCE(MIN(sc.`CODIGO_ATB_COLOR`), \'\') AS `CODIGO_ATB_COLOR`,\r\n  AVG(L.`PRECIO_COMPRA_SIVA_ARTICULO_DEVCLIN`) AS `PRECIO_COMPRA`,\r\n  0                                 AS `PRECIO_VENTA`,\r\n  L.`ID_AC_PIVOT_DEVCLIN`           AS `ID_AC_PIVOT`,\r\n  ac.`NOMBRE_AC`,\r\n  COALESCE(ac.`NOMBRE_CORTO_AC`, UPPER(LEFT(ac.`NOMBRE_AC`, 8))) AS `NOMBRE_CORTO_AC`,\r\n  -- Almacen destino de la linea (clave de agrupacion). El JOIN a\r\n  -- fza_almacenes expone los campos descriptivos del almacen para\r\n  -- que el .frx los pueda imprimir junto a cada linea. Si la\r\n  -- cabecera CODIGO_ALM_DEVC coincide con todas las lineas, ambos\r\n  -- niveles muestran lo mismo; en devoluciones agrupados con varios\r\n  -- almacenes, cada linea reflejara su propio destino.\r\n  L.`CODIGO_ALMACEN_DEVCLIN`        AS `CODIGO_ALM_DEVCLIN`,\r\n  MIN(alm.`CODIGO_EMP_ALM`)         AS `CODIGO_EMP_ALM_DEVCLIN`,\r\n  MIN(alm.`NOMBRE_ALM_ALM`)         AS `NOMBRE_ALM_DEVCLIN`,\r\n  MIN(alm.`DIRECCION_ALM`)          AS `DIRECCION_ALM_DEVCLIN`,\r\n  MIN(alm.`CODIGO_POSTAL_ALM`)      AS `CODIGO_POSTAL_ALM_DEVCLIN`,\r\n  MIN(alm.`POBLACION_ALM`)          AS `POBLACION_ALM_DEVCLIN`,\r\n  MIN(alm.`PROVINCIA_ALM`)          AS `PROVINCIA_ALM_DEVCLIN`,\r\n  MIN(alm.`TELEFONO_ALM`)           AS `TELEFONO_ALM_DEVCLIN`,\r\n  MIN(alm.`EMAIL_ALM`)              AS `EMAIL_ALM_DEVCLIN`,\r\n  SUM(L.`CANTIDAD_DEVCLIN`)         AS `TOTAL_UNIDADES`,\r\n  SUM(L.`TOTAL_DEVCLIN`)            AS `TOTAL_LINEA`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  1 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T01`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  2 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T02`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  3 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T03`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  4 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T04`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  5 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T05`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  6 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T06`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  7 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T07`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  8 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T08`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` =  9 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T09`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 10 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T10`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 11 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T11`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 12 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T12`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 13 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T13`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 14 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T14`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 15 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T15`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 16 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T16`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 17 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T17`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 18 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T18`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 19 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T19`,\r\n  COALESCE(SUM(CASE WHEN p.`POSICION` = 20 THEN L.`CANTIDAD_DEVCLIN` END), 0) AS `T20`\r\nFROM `fza_devoluciones_compra_lineas` L\r\nLEFT JOIN `fza_atributos_conjuntos` ac\r\n       ON ac.`ID_AC` = L.`ID_AC_PIVOT_DEVCLIN`\r\nLEFT JOIN `sku_talla` st\r\n       ON st.`CODIGO_UNIDAD` = L.`CODIGO_UNIDAD_DEVCLIN`\r\nLEFT JOIN `pos_acd` p\r\n       ON p.`ID_AC` = L.`ID_AC_PIVOT_DEVCLIN`\r\n      AND p.`ID_AV` = st.`ID_AV_TALLA`\r\nLEFT JOIN `sku_color` sc\r\n       ON sc.`CODIGO_UNIDAD` = L.`CODIGO_UNIDAD_DEVCLIN`\r\nLEFT JOIN `fza_almacenes` alm\r\n       ON alm.`CODIGO_ALM_ALM` = L.`CODIGO_ALMACEN_DEVCLIN`\r\nGROUP BY\r\n  L.`SERIE_DEVC_DEVCLIN`, L.`NUMERO_DEVC_DEVCLIN`,\r\n  L.`CODIGO_ART_DEVCLIN`,\r\n  L.`ID_AC_PIVOT_DEVCLIN`, ac.`NOMBRE_AC`, ac.`NOMBRE_CORTO_AC`,\r\n  sc.`CODIGO_ATB_COLOR`, sc.`NOMBRE_COLOR`,\r\n  SUBSTRING_INDEX(SUBSTRING_INDEX(L.`CODIGO_UNIDAD_DEVCLIN`, \'/\', 2), \'/\', -1),\r\n  L.`CODIGO_ALMACEN_DEVCLIN`;\r\n\r\n-- ---------------------------------------------------------------------------\r\n-- 3. Guias de tallas (mismas que en sesiones — depende solo de conjuntos)\r\n-- ---------------------------------------------------------------------------\r\nCREATE OR REPLACE VIEW `vi_devoluciones_compra_guias_print` AS\r\nWITH `pos_acd` AS (\r\n  SELECT\r\n    acd.`ID_AC_ACD` AS `ID_AC`,\r\n    acd.`ID_AV_ACD` AS `ID_AV`,\r\n    av.`AV`,\r\n    ROW_NUMBER() OVER (\r\n      PARTITION BY acd.`ID_AC_ACD`\r\n      ORDER BY acd.`ORDEN_ACD`, acd.`ID_AV_ACD`\r\n    ) AS `POSICION`\r\n  FROM `fza_atributos_conjuntos_det` acd\r\n  INNER JOIN `fza_atributos_valores` av ON av.`ID_AV` = acd.`ID_AV_ACD`\r\n)\r\nSELECT\r\n  ac.`ID_AC`,\r\n  ac.`NOMBRE_AC`,\r\n  COALESCE(ac.`NOMBRE_CORTO_AC`, UPPER(LEFT(ac.`NOMBRE_AC`, 8))) AS `NOMBRE_CORTO_AC`,\r\n  MAX(CASE WHEN p.`POSICION` =  1 THEN p.`AV` END) AS `T01`,\r\n  MAX(CASE WHEN p.`POSICION` =  2 THEN p.`AV` END) AS `T02`,\r\n  MAX(CASE WHEN p.`POSICION` =  3 THEN p.`AV` END) AS `T03`,\r\n  MAX(CASE WHEN p.`POSICION` =  4 THEN p.`AV` END) AS `T04`,\r\n  MAX(CASE WHEN p.`POSICION` =  5 THEN p.`AV` END) AS `T05`,\r\n  MAX(CASE WHEN p.`POSICION` =  6 THEN p.`AV` END) AS `T06`,\r\n  MAX(CASE WHEN p.`POSICION` =  7 THEN p.`AV` END) AS `T07`,\r\n  MAX(CASE WHEN p.`POSICION` =  8 THEN p.`AV` END) AS `T08`,\r\n  MAX(CASE WHEN p.`POSICION` =  9 THEN p.`AV` END) AS `T09`,\r\n  MAX(CASE WHEN p.`POSICION` = 10 THEN p.`AV` END) AS `T10`,\r\n  MAX(CASE WHEN p.`POSICION` = 11 THEN p.`AV` END) AS `T11`,\r\n  MAX(CASE WHEN p.`POSICION` = 12 THEN p.`AV` END) AS `T12`,\r\n  MAX(CASE WHEN p.`POSICION` = 13 THEN p.`AV` END) AS `T13`,\r\n  MAX(CASE WHEN p.`POSICION` = 14 THEN p.`AV` END) AS `T14`,\r\n  MAX(CASE WHEN p.`POSICION` = 15 THEN p.`AV` END) AS `T15`,\r\n  MAX(CASE WHEN p.`POSICION` = 16 THEN p.`AV` END) AS `T16`,\r\n  MAX(CASE WHEN p.`POSICION` = 17 THEN p.`AV` END) AS `T17`,\r\n  MAX(CASE WHEN p.`POSICION` = 18 THEN p.`AV` END) AS `T18`,\r\n  MAX(CASE WHEN p.`POSICION` = 19 THEN p.`AV` END) AS `T19`,\r\n  MAX(CASE WHEN p.`POSICION` = 20 THEN p.`AV` END) AS `T20`\r\nFROM `fza_atributos_conjuntos` ac\r\nINNER JOIN `pos_acd` p ON p.`ID_AC` = ac.`ID_AC`\r\nWHERE p.`POSICION` <= 20\r\n  AND ac.`ESACTIVO_AC` = \'S\'\r\nGROUP BY ac.`ID_AC`, ac.`NOMBRE_AC`, ac.`NOMBRE_CORTO_AC`;\r\n', '2026-06-21 17:26:44', '2026-06-21 17:26:44', 'Administrador', 'Administrador'),
  ('450', 'vi_compras_sesiones_cab_print_formato', '-- Anyade ESFORMATO_DISTRIBUIDO_SES a vi_compras_sesiones_cab_print.\r\n-- Necesario para que la plantilla de impresion pueda mostrar la columna\r\n-- \'Almacen\' SOLO cuando la sesion sea distribuida. CREATE OR REPLACE,\r\n-- script idempotente.\r\n\r\nCREATE OR REPLACE VIEW `vi_compras_sesiones_cab_print` AS\r\nSELECT\r\n  ses.`SERIE_SES`,\r\n  ses.`NUMERO_SES`,\r\n  ses.`FECHA_SES`,\r\n  ses.`ESTADO_SES`,\r\n  ses.`REF_PRV_SES`,\r\n  ses.`COMENTARIOS_SES`,\r\n  ses.`PORCENTAJE_MARGEN_SES`,\r\n  ses.`MULTIPLO_REDONDEO_SES`,\r\n  ses.`AJUSTE_FINAL_SES`,\r\n  ses.`MONEDA_SES`,\r\n  ses.`TIPO_IVA_SES`,\r\n  ses.`CODIGO_IVA_SES`,\r\n  ses.`ESVARIOS_TIPOS_IVA_SES`,\r\n  ses.`ESIVA_RECARGO_COMPRAS_SES`,\r\n  ses.`PORCENTAJE_IVAN_SES`,\r\n  ses.`TOTAL_BASEI_IVAN_SES`,\r\n  ses.`TOTAL_IVAN_SES`,\r\n  ses.`PORCENTAJE_REN_SES`,\r\n  ses.`TOTAL_REN_SES`,\r\n  ses.`PORCENTAJE_IVAR_SES`,\r\n  ses.`TOTAL_BASEI_IVAR_SES`,\r\n  ses.`TOTAL_IVAR_SES`,\r\n  ses.`PORCENTAJE_RER_SES`,\r\n  ses.`TOTAL_RER_SES`,\r\n  ses.`PORCENTAJE_IVAS_SES`,\r\n  ses.`TOTAL_BASEI_IVAS_SES`,\r\n  ses.`TOTAL_IVAS_SES`,\r\n  ses.`PORCENTAJE_RES_SES`,\r\n  ses.`TOTAL_RES_SES`,\r\n  ses.`PORCENTAJE_IVAE_SES`,\r\n  ses.`TOTAL_BASEI_IVAE_SES`,\r\n  ses.`TOTAL_IVAE_SES`,\r\n  ses.`PORCENTAJE_REE_SES`,\r\n  ses.`TOTAL_REE_SES`,\r\n  ses.`PORCENTAJE_RETENCION_SES`,\r\n  ses.`TOTAL_RETENCION_SES`,\r\n  ses.`TOTAL_BRUTO_SES`,\r\n  ses.`TOTAL_BASES_SES`,\r\n  ses.`TOTAL_IMPUESTOS_SES`,\r\n  ses.`TOTAL_SES`,\r\n  ses.`TOTAL_LIQUIDO_SES`,\r\n  ses.`ESFORMATO_DISTRIBUIDO_SES`,\r\n  ses.`CODIGO_EMP_SES`,\r\n  emp.`RAZON_SOCIAL_EMP`,\r\n  emp.`DIRECCION1_EMP`,\r\n  emp.`CODIGO_POSTAL_EMP`,\r\n  emp.`POBLACION_EMP`,\r\n  emp.`PROVINCIA_EMP`,\r\n  emp.`NIF_EMP`        AS `CIF_EMP`,\r\n  emp.`MOVIL_EMP`      AS `TELEFONO1_EMP`,\r\n  ses.`CODIGO_PRV_SES`,\r\n  prv.`RAZON_SOCIAL_PRV`,\r\n  prv.`DIRECCION1_PRV`,\r\n  prv.`CODIGO_POSTAL_PRV`,\r\n  prv.`POBLACION_PRV`,\r\n  prv.`PROVINCIA_PRV`,\r\n  prv.`NIF_PRV`        AS `CIF_PRV`,\r\n  COALESCE(prv.`TELEFONO_PRV`, prv.`MOVIL_PRV`) AS `TELEFONO1_PRV`,\r\n  ses.`CODIGO_TAR_SES`,\r\n  ses.`CODIGO_FAM_SES`,\r\n  ses.`CODIGO_ALM_SES`,\r\n  ses.`INSTANTE_ALTA`,\r\n  ses.`USUARIO_ALTA`,\r\n  (SELECT COALESCE(SUM(`TOTAL_UNIDADES_SESLIN`), 0)\r\n     FROM `fza_compras_sesiones_lineas` lin\r\n    WHERE lin.`SERIE_SES_SESLIN`  = ses.`SERIE_SES`\r\n      AND lin.`NUMERO_SES_SESLIN` = ses.`NUMERO_SES`) AS `TOTAL_UNIDADES_SES`,\r\n  (SELECT COALESCE(SUM(`TOTAL_LINEA_SESLIN`), 0)\r\n     FROM `fza_compras_sesiones_lineas` lin\r\n    WHERE lin.`SERIE_SES_SESLIN`  = ses.`SERIE_SES`\r\n      AND lin.`NUMERO_SES_SESLIN` = ses.`NUMERO_SES`) AS `TOTAL_LINEAS_SES`,\r\n  (SELECT COUNT(*)\r\n     FROM `fza_compras_sesiones_lineas` lin\r\n    WHERE lin.`SERIE_SES_SESLIN`  = ses.`SERIE_SES`\r\n      AND lin.`NUMERO_SES_SESLIN` = ses.`NUMERO_SES`) AS `NUM_LINEAS_SES`\r\nFROM `fza_compras_sesiones` ses\r\nLEFT JOIN `fza_empresas`     emp ON emp.`CODIGO_EMP_EMP` = ses.`CODIGO_EMP_SES`\r\nLEFT JOIN `fza_proveedores`  prv ON prv.`CODIGO_PRV_PRV` = ses.`CODIGO_PRV_SES`;\r\n', '2026-06-21 17:26:52', '2026-06-21 17:26:52', 'Administrador', 'Administrador'),
  ('452', 'compras_sesiones_recalcular_totales', '-- Recalcula totales historicos de sesiones de compra desde celdas y lineas.\r\n-- Ejecutar una vez despues de aplicar compras_sesiones_totales_iva.sql.\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_lineas_totales;\r\nCREATE TEMPORARY TABLE tmp_ses_lineas_totales AS\r\nSELECT L.SERIE_SES_SESLIN AS SERIE_SES,\r\n       L.NUMERO_SES_SESLIN AS NUMERO_SES,\r\n       L.LINEA_SESLIN AS LINEA_SES,\r\n       COALESCE(SUM(C.CANTIDAD_SESCEL), 0) AS TOTAL_UNIDADES,\r\n       COALESCE(SUM(C.CANTIDAD_SESCEL), 0) *\r\n       COALESCE(L.PRECIO_COMPRA_SESLIN, 0) AS TOTAL_LINEA\r\n  FROM fza_compras_sesiones_lineas L\r\n  LEFT JOIN fza_compras_sesiones_celdas C\r\n    ON C.SERIE_SES_SESCEL = L.SERIE_SES_SESLIN\r\n   AND C.NUMERO_SES_SESCEL = L.NUMERO_SES_SESLIN\r\n   AND C.LINEA_SES_SESCEL = L.LINEA_SESLIN\r\n GROUP BY L.SERIE_SES_SESLIN,\r\n          L.NUMERO_SES_SESLIN,\r\n          L.LINEA_SESLIN,\r\n          L.PRECIO_COMPRA_SESLIN;\r\nUPDATE fza_compras_sesiones_lineas L\r\n  JOIN tmp_ses_lineas_totales T\r\n    ON T.SERIE_SES = L.SERIE_SES_SESLIN\r\n   AND T.NUMERO_SES = L.NUMERO_SES_SESLIN\r\n   AND T.LINEA_SES = L.LINEA_SESLIN\r\n   SET L.TOTAL_UNIDADES_SESLIN = T.TOTAL_UNIDADES,\r\n       L.TOTAL_LINEA_SESLIN = T.TOTAL_LINEA;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_iva_empresa;\r\nCREATE TEMPORARY TABLE tmp_ses_iva_empresa AS\r\nSELECT E.CODIGO_EMP_EMP,\r\n       MIN(I.CODIGO_IVA) AS CODIGO_IVA\r\n  FROM fza_empresas E\r\n  JOIN fza_ivas_grupos G\r\n    ON G.IVA_IVAGRP = E.GRUPO_ZONA_IVA_EMP\r\n  JOIN fza_ivas I\r\n    ON I.IVA_IVAGRP = G.IVA_IVAGRP\r\n WHERE G.ESDEFAULT_IVA_IVAGRP = \'S\'\r\n GROUP BY E.CODIGO_EMP_EMP;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_iva;\r\nCREATE TEMPORARY TABLE tmp_ses_iva AS\r\nSELECT S.SERIE_SES,\r\n       S.NUMERO_SES,\r\n       COALESCE(NULLIF(S.CODIGO_IVA_SES, \'\'),\r\n                IE.CODIGO_IVA) AS CODIGO_IVA,\r\n       COALESCE(IVS.PORCENTAJE_NORMAL_IVA,\r\n                IVE.PORCENTAJE_NORMAL_IVA,\r\n                0) AS IVAN,\r\n       COALESCE(IVS.PORCENTAJE_REDUCIDO_IVA,\r\n                IVE.PORCENTAJE_REDUCIDO_IVA,\r\n                0) AS IVAR,\r\n       COALESCE(IVS.PORCENTAJE_SUPERREDUCIDO_IVA,\r\n                IVE.PORCENTAJE_SUPERREDUCIDO_IVA,\r\n                0) AS IVAS,\r\n       COALESCE(IVS.PORCENTAJE_EXENTO_IVA,\r\n                IVE.PORCENTAJE_EXENTO_IVA,\r\n                0) AS IVAE,\r\n       COALESCE(IVS.PORCENTAJE_NORMAL_RE_IVA,\r\n                IVE.PORCENTAJE_NORMAL_RE_IVA,\r\n                0) AS REN,\r\n       COALESCE(IVS.PORCENTAJE_REDUCIDO_RE_IVA,\r\n                IVE.PORCENTAJE_REDUCIDO_RE_IVA,\r\n                0) AS RER,\r\n       COALESCE(IVS.PORCENTAJE_SUPERREDUCIDO_RE_IVA,\r\n                IVE.PORCENTAJE_SUPERREDUCIDO_RE_IVA,\r\n                0) AS RES,\r\n       COALESCE(IVS.PORCENTAJE_EXENTO_RE_IVA,\r\n                IVE.PORCENTAJE_EXENTO_RE_IVA,\r\n                0) AS REE,\r\n       COALESCE(NULLIF(S.ESIVA_RECARGO_COMPRAS_SES, \'\'),\r\n                NULLIF(E.ESIVA_RECARGO_COMPRAS_EMP, \'\'),\r\n                \'N\') AS ESRECARGO,\r\n       COALESCE(S.PORCENTAJE_RETENCION_SES, 0) AS PORRET\r\n  FROM fza_compras_sesiones S\r\n  LEFT JOIN fza_empresas E\r\n    ON E.CODIGO_EMP_EMP = S.CODIGO_EMP_SES\r\n  LEFT JOIN fza_ivas IVS\r\n    ON IVS.CODIGO_IVA = NULLIF(S.CODIGO_IVA_SES, \'\')\r\n  LEFT JOIN tmp_ses_iva_empresa IE\r\n    ON IE.CODIGO_EMP_EMP = S.CODIGO_EMP_SES\r\n  LEFT JOIN fza_ivas IVE\r\n    ON IVE.CODIGO_IVA = IE.CODIGO_IVA;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_bases;\r\nCREATE TEMPORARY TABLE tmp_ses_bases AS\r\nSELECT L.SERIE_SES_SESLIN AS SERIE_SES,\r\n       L.NUMERO_SES_SESLIN AS NUMERO_SES,\r\n       CASE UPPER(TRIM(CASE\r\n                         WHEN COALESCE(S.ESVARIOS_TIPOS_IVA_SES, \'N\') = \'S\' AND\r\n                              COALESCE(NULLIF(L.TIPO_IVA_SESLIN, \'\'), \'\') <> \'\' THEN\r\n                           L.TIPO_IVA_SESLIN\r\n                         ELSE\r\n                           S.TIPO_IVA_SES\r\n                       END))\r\n         WHEN \'R\' THEN\r\n           \'R\'\r\n         WHEN \'S\' THEN\r\n           \'S\'\r\n         WHEN \'E\' THEN\r\n           \'E\'\r\n         ELSE\r\n           \'N\'\r\n       END AS TIPO_IVA,\r\n       SUM(COALESCE(L.TOTAL_LINEA_SESLIN, 0)) AS BASE\r\n  FROM fza_compras_sesiones_lineas L\r\n  JOIN fza_compras_sesiones S\r\n    ON S.SERIE_SES = L.SERIE_SES_SESLIN\r\n   AND S.NUMERO_SES = L.NUMERO_SES_SESLIN\r\n GROUP BY L.SERIE_SES_SESLIN,\r\n          L.NUMERO_SES_SESLIN,\r\n          CASE UPPER(TRIM(CASE\r\n                            WHEN COALESCE(S.ESVARIOS_TIPOS_IVA_SES, \'N\') = \'S\' AND\r\n                                 COALESCE(NULLIF(L.TIPO_IVA_SESLIN, \'\'), \'\') <> \'\' THEN\r\n                              L.TIPO_IVA_SESLIN\r\n                            ELSE\r\n                              S.TIPO_IVA_SES\r\n                          END))\r\n            WHEN \'R\' THEN\r\n              \'R\'\r\n            WHEN \'S\' THEN\r\n              \'S\'\r\n            WHEN \'E\' THEN\r\n              \'E\'\r\n            ELSE\r\n              \'N\'\r\n          END;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen_base;\r\nCREATE TEMPORARY TABLE tmp_ses_resumen_base AS\r\nSELECT S.SERIE_SES,\r\n       S.NUMERO_SES,\r\n       I.CODIGO_IVA,\r\n       I.IVAN,\r\n       I.IVAR,\r\n       I.IVAS,\r\n       I.IVAE,\r\n       I.REN,\r\n       I.RER,\r\n       I.RES,\r\n       I.REE,\r\n       I.ESRECARGO,\r\n       I.PORRET,\r\n       COALESCE(SUM(CASE WHEN B.TIPO_IVA = \'N\' THEN B.BASE ELSE 0 END), 0) AS BASE_N,\r\n       COALESCE(SUM(CASE WHEN B.TIPO_IVA = \'R\' THEN B.BASE ELSE 0 END), 0) AS BASE_R,\r\n       COALESCE(SUM(CASE WHEN B.TIPO_IVA = \'S\' THEN B.BASE ELSE 0 END), 0) AS BASE_S,\r\n       COALESCE(SUM(CASE WHEN B.TIPO_IVA = \'E\' THEN B.BASE ELSE 0 END), 0) AS BASE_E\r\n  FROM fza_compras_sesiones S\r\n  LEFT JOIN tmp_ses_iva I\r\n    ON I.SERIE_SES = S.SERIE_SES\r\n   AND I.NUMERO_SES = S.NUMERO_SES\r\n  LEFT JOIN tmp_ses_bases B\r\n    ON B.SERIE_SES = S.SERIE_SES\r\n   AND B.NUMERO_SES = S.NUMERO_SES\r\n GROUP BY S.SERIE_SES,\r\n          S.NUMERO_SES,\r\n          I.CODIGO_IVA,\r\n          I.IVAN,\r\n          I.IVAR,\r\n          I.IVAS,\r\n          I.IVAE,\r\n          I.REN,\r\n          I.RER,\r\n          I.RES,\r\n          I.REE,\r\n          I.ESRECARGO,\r\n          I.PORRET;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen_importes;\r\nCREATE TEMPORARY TABLE tmp_ses_resumen_importes AS\r\nSELECT R.SERIE_SES,\r\n       R.NUMERO_SES,\r\n       R.CODIGO_IVA,\r\n       R.IVAN,\r\n       R.IVAR,\r\n       R.IVAS,\r\n       R.IVAE,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.REN ELSE 0 END AS REN,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.RER ELSE 0 END AS RER,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.RES ELSE 0 END AS RES,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.REE ELSE 0 END AS REE,\r\n       R.PORRET,\r\n       R.BASE_N,\r\n       R.BASE_R,\r\n       R.BASE_S,\r\n       R.BASE_E,\r\n       R.BASE_N * R.IVAN / 100 AS IVA_N,\r\n       R.BASE_R * R.IVAR / 100 AS IVA_R,\r\n       R.BASE_S * R.IVAS / 100 AS IVA_S,\r\n       R.BASE_E * R.IVAE / 100 AS IVA_E,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.BASE_N * R.REN / 100 ELSE 0 END AS RE_N,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.BASE_R * R.RER / 100 ELSE 0 END AS RE_R,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.BASE_S * R.RES / 100 ELSE 0 END AS RE_S,\r\n       CASE WHEN R.ESRECARGO = \'S\' THEN R.BASE_E * R.REE / 100 ELSE 0 END AS RE_E\r\n  FROM tmp_ses_resumen_base R;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen;\r\nCREATE TEMPORARY TABLE tmp_ses_resumen AS\r\nSELECT R.SERIE_SES,\r\n       R.NUMERO_SES,\r\n       R.CODIGO_IVA,\r\n       R.IVAN,\r\n       R.IVAR,\r\n       R.IVAS,\r\n       R.IVAE,\r\n       R.REN,\r\n       R.RER,\r\n       R.RES,\r\n       R.REE,\r\n       R.PORRET,\r\n       R.BASE_N,\r\n       R.BASE_R,\r\n       R.BASE_S,\r\n       R.BASE_E,\r\n       R.IVA_N,\r\n       R.IVA_R,\r\n       R.IVA_S,\r\n       R.IVA_E,\r\n       R.RE_N,\r\n       R.RE_R,\r\n       R.RE_S,\r\n       R.RE_E,\r\n       R.BASE_N + R.BASE_R + R.BASE_S + R.BASE_E AS TOTAL_BASES,\r\n       R.IVA_N + R.IVA_R + R.IVA_S + R.IVA_E +\r\n       R.RE_N + R.RE_R + R.RE_S + R.RE_E AS TOTAL_IMPUESTOS,\r\n       (R.BASE_N + R.BASE_R + R.BASE_S + R.BASE_E) *\r\n       R.PORRET / 100 AS TOTAL_RETENCION\r\n  FROM tmp_ses_resumen_importes R;\r\nUPDATE fza_compras_sesiones S\r\n  JOIN tmp_ses_resumen R\r\n    ON R.SERIE_SES = S.SERIE_SES\r\n   AND R.NUMERO_SES = S.NUMERO_SES\r\n   SET S.CODIGO_IVA_SES = R.CODIGO_IVA,\r\n       S.PORCENTAJE_IVAN_SES = R.IVAN,\r\n       S.PORCENTAJE_IVAR_SES = R.IVAR,\r\n       S.PORCENTAJE_IVAS_SES = R.IVAS,\r\n       S.PORCENTAJE_IVAE_SES = R.IVAE,\r\n       S.PORCENTAJE_REN_SES = R.REN,\r\n       S.PORCENTAJE_RER_SES = R.RER,\r\n       S.PORCENTAJE_RES_SES = R.RES,\r\n       S.PORCENTAJE_REE_SES = R.REE,\r\n       S.TOTAL_BASEI_IVAN_SES = R.BASE_N,\r\n       S.TOTAL_BASEI_IVAR_SES = R.BASE_R,\r\n       S.TOTAL_BASEI_IVAS_SES = R.BASE_S,\r\n       S.TOTAL_BASEI_IVAE_SES = R.BASE_E,\r\n       S.TOTAL_IVAN_SES = R.IVA_N,\r\n       S.TOTAL_IVAR_SES = R.IVA_R,\r\n       S.TOTAL_IVAS_SES = R.IVA_S,\r\n       S.TOTAL_IVAE_SES = R.IVA_E,\r\n       S.TOTAL_REN_SES = R.RE_N,\r\n       S.TOTAL_RER_SES = R.RE_R,\r\n       S.TOTAL_RES_SES = R.RE_S,\r\n       S.TOTAL_REE_SES = R.RE_E,\r\n       S.TOTAL_BRUTO_SES = R.TOTAL_BASES,\r\n       S.TOTAL_BASES_SES = R.TOTAL_BASES,\r\n       S.TOTAL_IMPUESTOS_SES = R.TOTAL_IMPUESTOS,\r\n       S.TOTAL_RETENCION_SES = R.TOTAL_RETENCION,\r\n       S.TOTAL_SES = R.TOTAL_BASES + R.TOTAL_IMPUESTOS,\r\n       S.TOTAL_LIQUIDO_SES = R.TOTAL_BASES +\r\n                             R.TOTAL_IMPUESTOS -\r\n                             R.TOTAL_RETENCION;\r\nSELECT COUNT(*) AS SESIONES_RECALCULADAS\r\n  FROM tmp_ses_resumen;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen_importes;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_resumen_base;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_bases;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_iva;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_iva_empresa;\r\nDROP TEMPORARY TABLE IF EXISTS tmp_ses_lineas_totales;\r\n', '2026-06-21 19:53:59', '2026-06-21 19:53:59', 'Administrador', 'Administrador'),
  ('453', 'documentos_trabajo', '-- =============================================================================\r\n-- Documento de Trabajo: cabecera + lineas reutilizables\r\n-- =============================================================================\r\n-- Documento operativo no fiscal y sin movimiento de stock. Sirve como bolsa de\r\n-- unidades para preparar etiquetas, inventarios, traspasos o volcar articulos\r\n-- a otros documentos.\r\n-- No toca factuzam_original.sql. Idempotente: se puede ejecutar varias veces.\r\n-- =============================================================================\r\n\r\nCREATE TABLE IF NOT EXISTS `fza_documentos_trabajo` (\r\n  `ID_DTR` bigint(20) NOT NULL AUTO_INCREMENT,\r\n  `TITULO_DTR` varchar(200) NOT NULL,\r\n  `TIPO_DTR` varchar(20) NOT NULL DEFAULT \'GENERAL\',\r\n  `ESTADO_DTR` varchar(20) NOT NULL DEFAULT \'ABIERTO\',\r\n  `CODIGO_EMP_DTR` varchar(20) DEFAULT NULL,\r\n  `CODIGO_ALM_DTR` varchar(10) DEFAULT NULL,\r\n  `USUARIO_DTR` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  `INSTANTE_DOCUMENTO_DTR` datetime NOT NULL,\r\n  `OBSERVACIONES_DTR` text DEFAULT NULL,\r\n  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,\r\n  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT \'0000-00-00 00:00:00\',\r\n  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  PRIMARY KEY (`ID_DTR`)\r\n);\r\n\r\nSET @sExisteTitulo := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo\'\r\n     AND COLUMN_NAME = \'TITULO_DTR\'\r\n);\r\nSET @sExisteDescripcion := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo\'\r\n     AND COLUMN_NAME = \'DESCRIPCION_DTR\'\r\n);\r\nSET @sSql := IF(@sExisteTitulo = 0 AND @sExisteDescripcion > 0,\r\n  \'ALTER TABLE fza_documentos_trabajo CHANGE COLUMN DESCRIPCION_DTR TITULO_DTR varchar(200) NOT NULL\',\r\n  IF(@sExisteTitulo = 0,\r\n    \'ALTER TABLE fza_documentos_trabajo ADD COLUMN TITULO_DTR varchar(200) NOT NULL DEFAULT \'\'Documento de trabajo\'\' AFTER ID_DTR\',\r\n    \'SELECT \'\'TITULO_DTR ya existe, se omite\'\' AS info\'));\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nCREATE TABLE IF NOT EXISTS `fza_documentos_trabajo_lineas` (\r\n  `ID_DTL` bigint(20) NOT NULL AUTO_INCREMENT,\r\n  `ID_DTR_DTL` bigint(20) NOT NULL,\r\n  `LINEA_DTL` varchar(8) NOT NULL,\r\n  `CODIGO_ART_DTL` varchar(20) NOT NULL,\r\n  `CODIGO_UNIDAD_DTL` varchar(50) NOT NULL DEFAULT \'\',\r\n  `CODIGO_ALM_DTL` varchar(10) DEFAULT NULL,\r\n  `LOTE_DTL` varchar(50) NOT NULL DEFAULT \'\',\r\n  `FECHA_CADUCIDAD_DTL` date DEFAULT NULL,\r\n  `DESCRIPCION_ARTICULO_DTL` varchar(200) DEFAULT NULL,\r\n  `DESCRIPCION_UNIDAD_DTL` varchar(200) DEFAULT NULL,\r\n  `CANTIDAD_STOCK_DTL` decimal(19,6) NOT NULL DEFAULT 0.000000,\r\n  `CANTIDAD_DTL` decimal(19,6) NOT NULL DEFAULT 0.000000,\r\n  `INSTANTE_STOCK_DTL` datetime NOT NULL,\r\n  `ORIGEN_DTL` varchar(30) DEFAULT NULL,\r\n  `OBSERVACIONES_DTL` varchar(500) DEFAULT NULL,\r\n  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,\r\n  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT \'0000-00-00 00:00:00\',\r\n  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  PRIMARY KEY (`ID_DTL`),\r\n  UNIQUE KEY `UQ_DTL_DTR_LINEA` (`ID_DTR_DTL`, `LINEA_DTL`)\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS `fza_documentos_trabajo_compartidos` (\r\n  `ID_DTC` bigint(20) NOT NULL AUTO_INCREMENT,\r\n  `ID_DTR_DTC` bigint(20) NOT NULL,\r\n  `USUARIO_DTC` varchar(200) NOT NULL,\r\n  `USUARIO_GRUPO_DTC` varchar(200) NOT NULL DEFAULT \'\',\r\n  `TIPO_DESTINO_DTC` varchar(20) NOT NULL DEFAULT \'USUARIO\',\r\n  `PERMISO_DTC` varchar(20) NOT NULL DEFAULT \'LECTURA\',\r\n  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,\r\n  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT \'0000-00-00 00:00:00\',\r\n  `USUARIO_ALTA` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  `USUARIO_MODIF` varchar(100) NOT NULL DEFAULT \'SISTEMA\',\r\n  PRIMARY KEY (`ID_DTC`),\r\n  UNIQUE KEY `UQ_DTC_DTR_TIPO_DESTINO_USUARIO_GRUPO`\r\n    (`ID_DTR_DTC`, `TIPO_DESTINO_DTC`, `USUARIO_GRUPO_DTC`)\r\n);\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND INDEX_NAME = \'UQ_DTC_DTR_USUARIO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx > 0,\r\n  \'ALTER TABLE fza_documentos_trabajo_compartidos DROP INDEX UQ_DTC_DTR_USUARIO\',\r\n  \'SELECT \'\'UQ_DTC_DTR_USUARIO no existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sLongUsuarioDtc := (\r\n  SELECT COALESCE(MAX(CHARACTER_MAXIMUM_LENGTH), 0)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND COLUMN_NAME = \'USUARIO_DTC\'\r\n);\r\nSET @sSql := IF(@sLongUsuarioDtc < 200,\r\n  \'ALTER TABLE fza_documentos_trabajo_compartidos MODIFY COLUMN USUARIO_DTC varchar(200) NOT NULL\',\r\n  \'SELECT \'\'USUARIO_DTC ya tiene longitud suficiente, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND COLUMN_NAME = \'USUARIO_GRUPO_DTC\'\r\n);\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_documentos_trabajo_compartidos ADD COLUMN USUARIO_GRUPO_DTC varchar(200) NOT NULL DEFAULT \'\'\'\' AFTER USUARIO_DTC\',\r\n  \'SELECT \'\'USUARIO_GRUPO_DTC ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND COLUMN_NAME = \'TIPO_DESTINO_DTC\'\r\n);\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_documentos_trabajo_compartidos ADD COLUMN TIPO_DESTINO_DTC varchar(20) NOT NULL DEFAULT \'\'USUARIO\'\' AFTER USUARIO_GRUPO_DTC\',\r\n  \'SELECT \'\'TIPO_DESTINO_DTC ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nUPDATE `fza_documentos_trabajo_compartidos`\r\n   SET `USUARIO_GRUPO_DTC` = `USUARIO_DTC`\r\n WHERE COALESCE(`USUARIO_GRUPO_DTC`, \'\') = \'\';\r\n\r\nUPDATE `fza_documentos_trabajo_compartidos`\r\n   SET `TIPO_DESTINO_DTC` = \'USUARIO\'\r\n WHERE COALESCE(`TIPO_DESTINO_DTC`, \'\') = \'\';\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND INDEX_NAME = \'UQ_DTC_DTR_TIPO_DESTINO_USUARIO_GRUPO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE UNIQUE INDEX UQ_DTC_DTR_TIPO_DESTINO_USUARIO_GRUPO ON fza_documentos_trabajo_compartidos (ID_DTR_DTC, TIPO_DESTINO_DTC, USUARIO_GRUPO_DTC)\',\r\n  \'SELECT \'\'UQ_DTC_DTR_TIPO_DESTINO_USUARIO_GRUPO ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo\'\r\n     AND INDEX_NAME = \'IDX_DTR_ESTADO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTR_ESTADO ON fza_documentos_trabajo (ESTADO_DTR)\',\r\n  \'SELECT \'\'IDX_DTR_ESTADO ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo\'\r\n     AND INDEX_NAME = \'IDX_DTR_USUARIO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTR_USUARIO ON fza_documentos_trabajo (USUARIO_DTR)\',\r\n  \'SELECT \'\'IDX_DTR_USUARIO ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo\'\r\n     AND INDEX_NAME = \'IDX_DTR_INSTANTE\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTR_INSTANTE ON fza_documentos_trabajo (INSTANTE_DOCUMENTO_DTR)\',\r\n  \'SELECT \'\'IDX_DTR_INSTANTE ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_lineas\'\r\n     AND INDEX_NAME = \'IDX_DTL_DTR\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTL_DTR ON fza_documentos_trabajo_lineas (ID_DTR_DTL)\',\r\n  \'SELECT \'\'IDX_DTL_DTR ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_lineas\'\r\n     AND INDEX_NAME = \'IDX_DTL_UNIDAD\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTL_UNIDAD ON fza_documentos_trabajo_lineas (CODIGO_UNIDAD_DTL)\',\r\n  \'SELECT \'\'IDX_DTL_UNIDAD ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_lineas\'\r\n     AND INDEX_NAME = \'IDX_DTL_ART\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTL_ART ON fza_documentos_trabajo_lineas (CODIGO_ART_DTL)\',\r\n  \'SELECT \'\'IDX_DTL_ART ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_lineas\'\r\n     AND INDEX_NAME = \'IDX_DTL_ALM\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTL_ALM ON fza_documentos_trabajo_lineas (CODIGO_ALM_DTL)\',\r\n  \'SELECT \'\'IDX_DTL_ALM ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND INDEX_NAME = \'IDX_DTC_USUARIO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTC_USUARIO ON fza_documentos_trabajo_compartidos (USUARIO_DTC)\',\r\n  \'SELECT \'\'IDX_DTC_USUARIO ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND INDEX_NAME = \'IDX_DTC_TIPO_DESTINO_USUARIO_GRUPO\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTC_TIPO_DESTINO_USUARIO_GRUPO ON fza_documentos_trabajo_compartidos (TIPO_DESTINO_DTC, USUARIO_GRUPO_DTC)\',\r\n  \'SELECT \'\'IDX_DTC_TIPO_DESTINO_USUARIO_GRUPO ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteIdx := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.STATISTICS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME = \'fza_documentos_trabajo_compartidos\'\r\n     AND INDEX_NAME = \'IDX_DTC_DTR\'\r\n);\r\nSET @sSql := IF(@sExisteIdx = 0,\r\n  \'CREATE INDEX IDX_DTC_DTR ON fza_documentos_trabajo_compartidos (ID_DTR_DTC)\',\r\n  \'SELECT \'\'IDX_DTC_DTR ya existe, se omite\'\' AS info\');\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nINSERT IGNORE INTO `fza_winforms`\r\n  (`CALL_WINF`, `CAPTION_WINF`, `MENUITEM_WINF`, `UNITF_WINF`,\r\n   `SHORTCUT_WINF`, `DATAMODULE_WINF`, `NUM_VENTANAS_WINF`)\r\nVALUES\r\n  (\'DocumentosTrabajo\', \'Documentos de Trabajo\', \'mnuDocumentosTrabajo\',\r\n   \'inMtoDocumentosTrabajo.TfrmMtoDocumentosTrabajo\', \'Ctrl+W\',\r\n   \'UniDataDocumentosTrabajo.TdmDocumentosTrabajo\', 5);\r\n\r\nUPDATE `fza_winforms`\r\n   SET `CAPTION_WINF` = \'Documentos de Trabajo\',\r\n       `MENUITEM_WINF` = \'mnuDocumentosTrabajo\',\r\n       `UNITF_WINF` = \'inMtoDocumentosTrabajo.TfrmMtoDocumentosTrabajo\',\r\n       `SHORTCUT_WINF` = \'Ctrl+W\',\r\n       `DATAMODULE_WINF` = \'UniDataDocumentosTrabajo.TdmDocumentosTrabajo\',\r\n       `NUM_VENTANAS_WINF` = 5\r\n WHERE `CALL_WINF` = \'DocumentosTrabajo\'\r\n   AND (COALESCE(`CAPTION_WINF`, \'\') <> \'Documentos de Trabajo\'\r\n        OR COALESCE(`MENUITEM_WINF`, \'\') <> \'mnuDocumentosTrabajo\'\r\n        OR COALESCE(`UNITF_WINF`, \'\') <>\r\n           \'inMtoDocumentosTrabajo.TfrmMtoDocumentosTrabajo\'\r\n        OR COALESCE(`SHORTCUT_WINF`, \'\') <> \'Ctrl+W\'\r\n        OR COALESCE(`DATAMODULE_WINF`, \'\') <>\r\n           \'UniDataDocumentosTrabajo.TdmDocumentosTrabajo\'\r\n        OR COALESCE(`NUM_VENTANAS_WINF`, 0) <> 5);\r\n\r\nUPDATE `fza_winforms`\r\n   SET `SHORTCUT_WINF` = \'Ctrl+Alt+Shift+P\'\r\n WHERE `CALL_WINF` = \'UsuariosPerfiles\'\r\n   AND COALESCE(`SHORTCUT_WINF`, \'\') <> \'Ctrl+Alt+Shift+P\';\r\n\r\nINSERT IGNORE INTO `fza_permisos`\r\n  (`USUARIO_GRUPO_PERM`, `CODIGO_PERM`, `VALOR_PERM`, `DESCRIPCION_PERM`,\r\n   `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`)\r\nVALUES\r\n  (\'Todos\', \'menu.DocumentosTrabajo\', \'S\', \'Documentos de Trabajo\',\r\n   current_timestamp(), \'SISTEMA\', \'SISTEMA\');\r\n', '2026-06-22 07:08:25', '2026-06-22 07:08:25', 'Administrador', 'Administrador'),
  ('454', 'vi_empresas_recargo_compras', '-- =============================================================================\r\n-- Repara vi_empresas para exponer ESIVA_RECARGO_COMPRAS_EMP\r\n-- =============================================================================\r\n-- El mantenimiento de empresas lee SELECT * FROM vi_empresas y graba contra\r\n-- fza_empresas usando ESIVA_RECARGO_COMPRAS_EMP. Si la vista no expone el\r\n-- campo, UniDAC no encuentra el parametro al grabar.\r\n-- Idempotente: anade la columna si falta y recrea la vista.\r\n-- =============================================================================\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_empresas\'\r\n     AND COLUMN_NAME  = \'ESIVA_RECARGO_COMPRAS_EMP\'\r\n);\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE fza_empresas\r\n     ADD COLUMN ESIVA_RECARGO_COMPRAS_EMP varchar(1) NULL DEFAULT \'\'N\'\'\r\n     AFTER ESRETENCIONES_EMP\',\r\n  \'SELECT \'\'ESIVA_RECARGO_COMPRAS_EMP ya existe, se omite\'\' AS info\'\r\n);\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\nUPDATE fza_empresas\r\n   SET ESIVA_RECARGO_COMPRAS_EMP = \'N\'\r\n WHERE ESIVA_RECARGO_COMPRAS_EMP IS NULL\r\n    OR ESIVA_RECARGO_COMPRAS_EMP = \'\';\r\nCREATE OR REPLACE ALGORITHM=UNDEFINED VIEW `vi_empresas` AS\r\nSELECT `fza_empresas`.`CODIGO_EMP_EMP`                AS `CODIGO_EMP_EMP`,\r\n       `fza_empresas`.`ORDEN_EMP`                     AS `ORDEN_EMP`,\r\n       `fza_empresas`.`ESACTIVO_EMP`                  AS `ESACTIVO_EMP`,\r\n       `fza_empresas`.`RAZON_SOCIAL_EMP`              AS `RAZON_SOCIAL_EMP`,\r\n       `fza_empresas`.`NIF_EMP`                       AS `NIF_EMP`,\r\n       `fza_empresas`.`MOVIL_EMP`                     AS `MOVIL_EMP`,\r\n       `fza_empresas`.`EMAIL_EMP`                     AS `EMAIL_EMP`,\r\n       `fza_empresas`.`DIRECCION1_EMP`                AS `DIRECCION1_EMP`,\r\n       `fza_empresas`.`DIRECCION2_EMP`                AS `DIRECCION2_EMP`,\r\n       `fza_empresas`.`CODIGO_POSTAL_EMP`             AS `CODIGO_POSTAL_EMP`,\r\n       `fza_empresas`.`POBLACION_EMP`                 AS `POBLACION_EMP`,\r\n       `fza_empresas`.`PROVINCIA_EMP`                 AS `PROVINCIA_EMP`,\r\n       `fza_empresas`.`NOMBRE_PAI_EMP`                AS `NOMBRE_PAI_EMP`,\r\n       `fza_empresas`.`CODIGO_PAI_EMP`                AS `CODIGO_PAI_EMP`,\r\n       `fza_empresas`.`IBAN_EMP`                      AS `IBAN_EMP`,\r\n       `fza_empresas`.`GRUPO_ZONA_IVA_EMP`            AS `GRUPO_ZONA_IVA_EMP`,\r\n       `fza_ivas_grupos`.`DESCRIPCION_IVA_IVAGRP`     AS `DESCRIPCION_IVA_IVAGRP`,\r\n       `fza_empresas`.`ESRETENCIONES_EMP`             AS `ESRETENCIONES_EMP`,\r\n       `fza_empresas`.`ESIVA_RECARGO_COMPRAS_EMP`     AS `ESIVA_RECARGO_COMPRAS_EMP`,\r\n       `fza_empresas`.`ESREGIMENESPECIALAGRICOLA_EMP` AS `ESREGIMENESPECIALAGRICOLA_EMP`,\r\n       `fza_empresas`.`TEXTO_LEGAL_FACTURA_EMP`       AS `TEXTO_LEGAL_FACTURA_EMP`,\r\n       `fza_empresas`.`FORMATO_DOCUMENTO_EMP`         AS `FORMATO_DOCUMENTO_EMP`,\r\n       `fza_empresas`.`CODIGO_CERTIFICADO_EMP`        AS `CODIGO_CERTIFICADO_EMP`,\r\n       `fza_empresas`.`TITULAR_CERTIFICADO_EMP`       AS `TITULAR_CERTIFICADO_EMP`,\r\n       `fza_empresas`.`TIPO_CERTIFICADO_EMP`          AS `TIPO_CERTIFICADO_EMP`,\r\n       `fza_empresas`.`FECHA_DESDE_CERTIFICADO_EMP`   AS `FECHA_DESDE_CERTIFICADO_EMP`,\r\n       `fza_empresas`.`FECHA_HASTA_CERTIFICADO_EMP`   AS `FECHA_HASTA_CERTIFICADO_EMP`,\r\n       `fza_empresas`.`INSTANTE_MODIF`                AS `INSTANTE_MODIF`,\r\n       `fza_empresas`.`INSTANTE_ALTA`                 AS `INSTANTE_ALTA`,\r\n       `fza_empresas`.`USUARIO_ALTA`                  AS `USUARIO_ALTA`,\r\n       `fza_empresas`.`USUARIO_MODIF`                 AS `USUARIO_MODIF`\r\n  FROM (`fza_empresas`\r\n        LEFT JOIN `fza_ivas_grupos`\r\n          ON (`fza_empresas`.`GRUPO_ZONA_IVA_EMP` =\r\n              `fza_ivas_grupos`.`IVA_IVAGRP`))\r\n ORDER BY `fza_empresas`.`ORDEN_EMP`;\r\n', '2026-06-23 16:34:02', '2026-06-23 16:34:02', 'Administrador', 'Administrador'),
  ('455', 'sepa_remesas_venta_datos', '-- =============================================================================\r\n-- Datos SEPA para remesas de venta\r\n-- =============================================================================\r\n-- Anade los datos maestros necesarios para generar adeudos SEPA 19.14:\r\n--   - Codigo acreedor SEPA en la cuenta bancaria de la empresa.\r\n--   - Mandato SEPA y fecha de firma en el cliente.\r\n--   - Tipo de secuencia SEPA en la remesa de venta.\r\n--\r\n-- Idempotente: se puede ejecutar varias veces. Cada columna se anade solo\r\n-- si no existe.\r\n-- =============================================================================\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_empresas_bancos\'\r\n     AND COLUMN_NAME  = \'CODIGO_ACREEDOR_SEPA_EMPBAN\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE `fza_empresas_bancos`\r\n     ADD COLUMN `CODIGO_ACREEDOR_SEPA_EMPBAN` varchar(35) NULL DEFAULT NULL\r\n       COMMENT \'\'Identificador de acreedor SEPA para adeudos\'\'\r\n       AFTER `BIC_EMPBAN`\',\r\n  \'SELECT \'\'CODIGO_ACREEDOR_SEPA_EMPBAN ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_clientes\'\r\n     AND COLUMN_NAME  = \'ID_MANDATO_SEPA_CLI\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE `fza_clientes`\r\n     ADD COLUMN `ID_MANDATO_SEPA_CLI` varchar(35) NULL DEFAULT NULL\r\n       COMMENT \'\'Identificador del mandato SEPA de adeudo\'\'\r\n       AFTER `IBAN_CLI`\',\r\n  \'SELECT \'\'ID_MANDATO_SEPA_CLI ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_clientes\'\r\n     AND COLUMN_NAME  = \'FECHA_FIRMA_MANDATO_SEPA_CLI\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE `fza_clientes`\r\n     ADD COLUMN `FECHA_FIRMA_MANDATO_SEPA_CLI` date NULL DEFAULT NULL\r\n       COMMENT \'\'Fecha de firma del mandato SEPA de adeudo\'\'\r\n       AFTER `ID_MANDATO_SEPA_CLI`\',\r\n  \'SELECT \'\'FECHA_FIRMA_MANDATO_SEPA_CLI ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nSET @sExisteCol := (\r\n  SELECT COUNT(*)\r\n    FROM INFORMATION_SCHEMA.COLUMNS\r\n   WHERE TABLE_SCHEMA = DATABASE()\r\n     AND TABLE_NAME   = \'fza_remesas_venta\'\r\n     AND COLUMN_NAME  = \'TIPO_SECUENCIA_SEPA_REMV\'\r\n);\r\n\r\nSET @sSql := IF(@sExisteCol = 0,\r\n  \'ALTER TABLE `fza_remesas_venta`\r\n     ADD COLUMN `TIPO_SECUENCIA_SEPA_REMV` varchar(4) NULL DEFAULT \'\'RCUR\'\'\r\n       COMMENT \'\'Secuencia SEPA del adeudo: FRST, RCUR, OOFF o FNAL\'\'\r\n       AFTER `NORMA_REMV`\',\r\n  \'SELECT \'\'TIPO_SECUENCIA_SEPA_REMV ya existe, se omite\'\' AS info\'\r\n);\r\n\r\nPREPARE stmt FROM @sSql;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\n\r\nUPDATE `fza_remesas_venta`\r\n   SET `TIPO_SECUENCIA_SEPA_REMV` = \'RCUR\'\r\n WHERE `TIPO_SECUENCIA_SEPA_REMV` IS NULL\r\n    OR TRIM(`TIPO_SECUENCIA_SEPA_REMV`) = \'\';\r\n', '2026-06-23 17:35:46', '2026-06-23 17:35:46', 'Administrador', 'Administrador'),
  ('456', 'facturas_simplificadas_cabecera_empresa', '-- =============================================================================\r\n-- Sincroniza cabeceras de facturas simplificadas con fza_empresas\r\n-- =============================================================================\r\n-- Actualiza los datos del emisor guardados en fza_facturas para todas las\r\n-- facturas simplificadas, tomando el contenido actual de fza_empresas segun\r\n-- CODIGO_EMP_FAC = CODIGO_EMP_EMP.\r\n-- No toca datos de cliente, totales, fechas, serie, numero ni estados\r\n-- Verifactu. Las facturas sin empresa coincidente se listan, pero no se\r\n-- actualizan.\r\n--\r\n-- Idempotente: solo actualiza cabeceras donde algun dato de empresa difiere.\r\n-- =============================================================================\r\n\r\nDROP TEMPORARY TABLE IF EXISTS tmp_fac_simplif_emp_cab;\r\n\r\nCREATE TEMPORARY TABLE tmp_fac_simplif_emp_cab AS\r\nSELECT fac.NUMERO_FAC,\r\n       fac.SERIE_FAC\r\n  FROM fza_facturas AS fac\r\n  JOIN fza_empresas AS emp\r\n    ON emp.CODIGO_EMP_EMP = fac.CODIGO_EMP_FAC\r\n WHERE fac.TIPO_FAC = \'SIMPLIFICADA\'\r\n   AND (\r\n       NOT (fac.RAZON_SOCIAL_EMPRESA_FAC <=>\r\n            emp.RAZON_SOCIAL_EMP)\r\n    OR NOT (fac.NIF_EMPRESA_FAC <=>\r\n            emp.NIF_EMP)\r\n    OR NOT (fac.MOVIL_EMPRESA_FAC <=>\r\n            emp.MOVIL_EMP)\r\n    OR NOT (fac.EMAIL_EMPRESA_FAC <=>\r\n            emp.EMAIL_EMP)\r\n    OR NOT (fac.DIRECCION1_EMPRESA_FAC <=>\r\n            emp.DIRECCION1_EMP)\r\n    OR NOT (fac.DIRECCION2_EMPRESA_FAC <=>\r\n            emp.DIRECCION2_EMP)\r\n    OR NOT (fac.POBLACION_EMPRESA_FAC <=>\r\n            emp.POBLACION_EMP)\r\n    OR NOT (fac.PROVINCIA_EMPRESA_FAC <=>\r\n            emp.PROVINCIA_EMP)\r\n    OR NOT (fac.CODIGO_PAI_EMPRESA_FAC <=>\r\n            emp.CODIGO_PAI_EMP)\r\n    OR NOT (fac.NOMBRE_PAI_EMPRESA_FAC <=>\r\n            emp.NOMBRE_PAI_EMP)\r\n    OR NOT (fac.CODIGO_POSTAL_EMPRESA_FAC <=>\r\n            emp.CODIGO_POSTAL_EMP)\r\n    OR NOT (fac.ESRETENCIONES_EMPRESA_FAC <=>\r\n            emp.ESRETENCIONES_EMP)\r\n    OR NOT (fac.GRUPO_ZONA_IVA_EMPRESA_FAC <=>\r\n            emp.GRUPO_ZONA_IVA_EMP)\r\n    OR NOT (fac.ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC <=>\r\n            emp.ESREGIMENESPECIALAGRICOLA_EMP)\r\n    OR NOT (fac.TEXTO_LEGAL_EMPRESA_FAC <=>\r\n            emp.TEXTO_LEGAL_FACTURA_EMP)\r\n   );\r\n\r\nSELECT COUNT(*) AS CABECERAS_SIMPLIFICADAS_A_ACTUALIZAR\r\n  FROM tmp_fac_simplif_emp_cab;\r\n\r\nSELECT fac.NUMERO_FAC,\r\n       fac.SERIE_FAC,\r\n       fac.CODIGO_EMP_FAC\r\n  FROM fza_facturas AS fac\r\n  LEFT JOIN fza_empresas AS emp\r\n    ON emp.CODIGO_EMP_EMP = fac.CODIGO_EMP_FAC\r\n WHERE fac.TIPO_FAC = \'SIMPLIFICADA\'\r\n   AND emp.CODIGO_EMP_EMP IS NULL;\r\n\r\nSTART TRANSACTION;\r\n\r\nUPDATE fza_facturas AS fac\r\n  JOIN tmp_fac_simplif_emp_cab AS tmp\r\n    ON tmp.NUMERO_FAC = fac.NUMERO_FAC\r\n   AND tmp.SERIE_FAC  = fac.SERIE_FAC\r\n  JOIN fza_empresas AS emp\r\n    ON emp.CODIGO_EMP_EMP = fac.CODIGO_EMP_FAC\r\n   SET fac.RAZON_SOCIAL_EMPRESA_FAC =\r\n       emp.RAZON_SOCIAL_EMP,\r\n       fac.NIF_EMPRESA_FAC =\r\n       emp.NIF_EMP,\r\n       fac.MOVIL_EMPRESA_FAC =\r\n       emp.MOVIL_EMP,\r\n       fac.EMAIL_EMPRESA_FAC =\r\n       emp.EMAIL_EMP,\r\n       fac.DIRECCION1_EMPRESA_FAC =\r\n       emp.DIRECCION1_EMP,\r\n       fac.DIRECCION2_EMPRESA_FAC =\r\n       emp.DIRECCION2_EMP,\r\n       fac.POBLACION_EMPRESA_FAC =\r\n       emp.POBLACION_EMP,\r\n       fac.PROVINCIA_EMPRESA_FAC =\r\n       emp.PROVINCIA_EMP,\r\n       fac.CODIGO_PAI_EMPRESA_FAC =\r\n       emp.CODIGO_PAI_EMP,\r\n       fac.NOMBRE_PAI_EMPRESA_FAC =\r\n       emp.NOMBRE_PAI_EMP,\r\n       fac.CODIGO_POSTAL_EMPRESA_FAC =\r\n       emp.CODIGO_POSTAL_EMP,\r\n       fac.ESRETENCIONES_EMPRESA_FAC =\r\n       emp.ESRETENCIONES_EMP,\r\n       fac.GRUPO_ZONA_IVA_EMPRESA_FAC =\r\n       emp.GRUPO_ZONA_IVA_EMP,\r\n       fac.ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC =\r\n       emp.ESREGIMENESPECIALAGRICOLA_EMP,\r\n       fac.TEXTO_LEGAL_EMPRESA_FAC =\r\n       emp.TEXTO_LEGAL_FACTURA_EMP,\r\n       fac.USUARIO_MODIF =\r\n       \'SCRIPT\';\r\n\r\nSELECT ROW_COUNT() AS CABECERAS_SIMPLIFICADAS_ACTUALIZADAS;\r\n\r\nCOMMIT;\r\n\r\nDROP TEMPORARY TABLE IF EXISTS tmp_fac_simplif_emp_cab;\r\n', '2026-06-25 08:03:35', '2026-06-25 08:03:35', 'Administrador', 'Administrador'),
