INSERT INTO `fza_usuarios_perfiles` (`USUARIO_GRUPO_USUPER`, `KEY_USUPER`, `SUBKEY_USUPER`, `VALUE_USUPER`, `VALUE_TEXT_USUPER`, `TYPE_BLOB_USUPER`, `VALUE_BLOB_USUPER`, `INSTANTE_MODIF`, `INSTANTE_ALTA`, `USUARIO_ALTA`, `USUARIO_MODIF`) VALUES
  ('Administrador', 'dmFacturas', 'unqryArtDataLinFac', 'SQL', 'select * \r\n  from vi_art_busquedas\r\n where (codigo_tarifa = :tarifa\r\n    or codigo_tarifa is null)\r\n   AND FECHA_DESDE_ARTTAR < :FECHA_FAC\r\n   AND (FECHA_HASTA_ARTTAR IS NULL\r\n        OR FECHA_HASTA_ARTTAR > :FECHA_FAC)\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryCliDataFac', 'SQL', 'select * from vi_cli_busquedas\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryConsolidacion', 'SQL', 'SELECT * FROM fza_facturas_consolidaciones\r\nWHERE NUMERO_FAC_FACCON = :NUMERO_FAC\r\nAND SERIE_FAC_FACCON = :SERIE_FAC\r\nORDER BY ID_FACCON DESC\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryEmpDataFac', 'SQL', 'SELECT * FROM VI_EMP_BUSQUEDAS\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryErrores', 'SQL', 'select *\r\nFROM fza_verifactu_eventos\r\norder by id_log desc\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryFacPrint', 'SQL', 'SELECT *\r\nfrom VI_FACTURAS_PRINT\r\nwhere SERIE_FAC = \'ANA/2023\' \r\nAND NUMERO_FAC = \'000003\'\r\norder by NUMERO_FAC Asc\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryFormaPago', 'SQL', 'select * from vi_formapago\r\n\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryIvas', 'SQL', 'SELECT * \r\nFROM VI_IVAS\r\n\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryIvasTipos', 'SQL', 'SELECT * \r\nFROM FZA_IVAS_TIPOS\r\n\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryLinFac', 'SQL', 'SELECT *\r\nFROM vi_FACTURAS_LINEAS\r\nwhere NUMERO_FAC_FACLIN = :NUMERO_FAC\r\nAND SERIE_FAC_FACLIN = :SERIE_FAC\r\norder by NUMERO_FAC_FACLIN, SERIE_FAC_FACLIN, LINEA_FACLIN ASC\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
  ('Administrador', 'dmFacturas', 'unqryLinFacPrint', 'SQL', 'SELECT *\r\n FROM vi_FACTURAS_LINEAS_print\r\nWHERE NUMERO_FAC_FACLIN = :NUMERO_FAC\r\n  AND SERIE_FAC_FACLIN = :SERIE_FAC\r\nORDER BY LINEA_FACLIN;\r\n', NULL, NULL, '2026-03-07 08:13:14', '2026-03-07 08:13:14', 'Administrador', 'Administrador'),
